53	{
54	//! Optimization-profile indices for the composable stack. Profile 0 is prefill, profile 1 is decode
55	//! (including speculative tree-verification / proposal / accept). These match the profile layout baked
56	//! into the engines by `llmBuilder`.
57	constexpr int32_t kPrefillProfile{0};
58	constexpr int32_t kDecodeProfile{1};
59	
60	//! Fires `context.onTokenGenerated` once per active slot using the most recent
61	//! token in `tokenIds`. Called at the end of prefill (one token sampled per
62	//! slot) and after every decode iteration so streaming consumers see every
63	//! emitted token in order.
64	inline void emitTokenCallbacks(rt::DecodingInferenceContext& context)
65	{
66	    if (!context.onTokenGenerated.has_value())
67	    {
68	        return;
69	    }
70	    auto const& callback = context.onTokenGenerated.value();
71	    for (int32_t i = 0; i < context.activeBatchSize; ++i)
72	    {
73	        auto const& slotTokens = context.tokenIds[i];
74	        if (slotTokens.empty())
75	        {
76	            continue;
77	        }
78	        bool const isFinished = context.finishedStates[i] != 0;
79	        callback(rt::TokenCallbackInfo{slotTokens.back(), i, context.generationRound, isFinished});
80	    }
81	}
82	
