89	bool needsDFlashDDTreeHybridBindings(DeploymentConfig const& deployment)
90	{
91	    return deployment.specConfig.has_value() && deployment.specDecodeMode() == SpecDecodeMode::kDFlash
92	        && deployment.specConfig->draftingTopK > 1 && deployment.base.numLinearAttnLayers > 0;
93	}
94	
95	void validateDFlashTreeMetadataBindings(DeploymentConfig const& deployment, EngineExecutor const& baseExecutor)
96	{
97	    if (!deployment.specConfig.has_value() || deployment.specDecodeMode() != SpecDecodeMode::kDFlash)
98	    {
99	        return;
100	    }
101	
102	    bool const hasTreeParentIds = baseExecutor.hasIOTensor(binding_names::kTreeParentIds);
103	    bool const hasTreeDepths = baseExecutor.hasIOTensor(binding_names::kTreeDepths);
104	    bool const hasTreeMetadata = hasTreeParentIds || hasTreeDepths;
105	    bool const usesDDTree = deployment.specConfig->draftingTopK > 1;
106	    if (hasTreeMetadata)
107	    {
108	        ELLM_CHECK(hasTreeParentIds && hasTreeDepths,
109	            std::string("DFlash tree-base engine must expose both INT32 tree metadata bindings '")
110	                + binding_names::kTreeParentIds + "' and '" + binding_names::kTreeDepths + "'.");
111	        ELLM_CHECK(baseExecutor.getBindingDataType(binding_names::kTreeParentIds) == DataType::kINT32
112	                && baseExecutor.getBindingDataType(binding_names::kTreeDepths) == DataType::kINT32,
113	            std::string("DFlash tree-base engine tree metadata bindings must be INT32: '")
114	                + binding_names::kTreeParentIds + "' and '" + binding_names::kTreeDepths + "'.");
115	        ELLM_CHECK(usesDDTree,
116	            std::string("DFlash base engine was exported with --dflash-tree-base, but runtime is configured for "
117	                        "linear DFlash because specDraftTopK=1. Use --specDraftTopK > 1 for DDTree, or re-export "
118	                        "the base model with --dflash-base for linear DFlash."));
119	    }
120	
121	    if (!needsDFlashDDTreeHybridBindings(deployment))
122	    {
123	        return;
124	    }
125	
126	    ELLM_CHECK(hasTreeParentIds && hasTreeDepths,
127	        std::string("DFlash DDTree hybrid base engine requires INT32 tree metadata bindings '")
128	            + binding_names::kTreeParentIds + "' and '" + binding_names::kTreeDepths
129	            + "'. Re-export the base model with --dflash-tree-base, then rebuild spec_base.engine.");
130	}
131	} // namespace
