133	LLMInferenceRuntime::LLMInferenceRuntime(std::string const& engineDir, std::string const& multimodalEngineDir,
134	    std::unordered_map<std::string, std::string> const& loraWeightsMap, SpecDecodeDraftingConfig const& draftingConfig,
135	    cudaStream_t stream)
136	{
137	    initializeCommon(engineDir, multimodalEngineDir, loraWeightsMap, draftingConfig, stream);
138	}
