140	LLMInferenceRuntime::LLMInferenceRuntime(std::string const& engineDir, std::string const& multimodalEngineDir,
141	    std::unordered_map<std::string, std::string> const& loraWeightsMap, cudaStream_t stream)
142	{
143	    initializeCommon(engineDir, multimodalEngineDir, loraWeightsMap, std::nullopt, stream);
144	}
145	
146	void LLMInferenceRuntime::initializeCommon(std::string const& engineDir, std::string const& multimodalEngineDir,
147	    std::unordered_map<std::string, std::string> const& loraWeightsMap,
148	    std::optional<SpecDecodeDraftingConfig> const& draftingConfig, cudaStream_t stream)
149	{
150	    // -----------------------------------------------------------------------
151	    // 1. Load shared embedding table (shared between base and draft models).
152	    // -----------------------------------------------------------------------
153	    std::filesystem::path const embeddingPath = std::filesystem::path(engineDir) / "embedding.safetensors";
154	    mEmbedding = loadEmbeddingTable(embeddingPath, stream);
155	
156	    // -----------------------------------------------------------------------
157	    // 2. Parse engine configurations and attach user drafting (bundle factory
158	    //    performs cross-engine consistency and drafting-vs-capacity checks).
159	    // -----------------------------------------------------------------------
160	    std::filesystem::path const engineDirPath{engineDir};
161	    std::filesystem::path const baseEnginePath
162	        = draftingConfig.has_value() ? engineDirPath / "spec_base.engine" : engineDirPath / "llm.engine";
163	    std::filesystem::path const baseConfigPath
164	        = draftingConfig.has_value() ? engineDirPath / "base_config.json" : engineDirPath / "config.json";
165	    std::optional<std::filesystem::path> const draftConfigPath = draftingConfig.has_value()
166	        ? std::optional<std::filesystem::path>{engineDirPath / "draft_config.json"}
167	        : std::nullopt;
168	
169	    mDeployment = createDeploymentConfig(baseConfigPath, draftConfigPath, draftingConfig);
170	
171	    ELLM_CHECK(mDeployment.base.numDeepstackFeatures <= 0 || !multimodalEngineDir.empty(),
172	        "--multimodalEngineDir is required for VLM engine.");
173	
174	    // -----------------------------------------------------------------------
175	    // 3. Construct Runners (registries built internally from the parsed configs).
176	    // -----------------------------------------------------------------------
177	    try
178	    {
179	        std::optional<int32_t> const specDecodeBaseOutputHiddenDim = mDeployment.specConfig.has_value()
180	            ? std::optional<int32_t>{mDeployment.specConfig->baseOutputHiddenDim}
181	            : std::nullopt;
182	        mBaseExecutor = EngineExecutor::createForLLM(baseEnginePath, mDeployment.base, specDecodeBaseOutputHiddenDim);
183	    }
184	    catch (std::exception const& e)
185	    {
186	        LOG_ERROR("Failed to initialize base EngineExecutor: %s", e.what());
187	        throw std::runtime_error("Failed to initialize base EngineExecutor: " + std::string(e.what()));
188	    }
189	    LOG_INFO("Base EngineExecutor successfully loaded from %s.", baseEnginePath.c_str());
190	
191	    // -----------------------------------------------------------------------
192	    // 4. Validate engine binding dtypes against the parsed configs.
193	    // -----------------------------------------------------------------------
194	    validateAgainstEngine(mDeployment.base, *mBaseExecutor, "base");
195	    validateDFlashTreeMetadataBindings(mDeployment, *mBaseExecutor);
196	
197	    // -----------------------------------------------------------------------
198	    // 5. Set runtime batch size.
199	    // -----------------------------------------------------------------------
200	    mMaxRuntimeBatchSize = mDeployment.maxRuntimeBatchSize();
201	    LOG_INFO("Runtime batch size set to: %d (from engine bundle)", mMaxRuntimeBatchSize);
202	
203	    // -----------------------------------------------------------------------
204	    // 6. SharedResources + PipelineIO. PipelineIO is held via unique_ptr so
205	    //    its address is stable for the TensorMap pointers below (TensorMap
206	    //    stores non-owning Tensor* into PipelineIO members).
207	    // -----------------------------------------------------------------------
208	    bool const hasDraft = draftingConfig.has_value();
209	    if (hasDraft)
210	    {
211	        mSharedResources
212	            = SharedResources::createForSpecDecode(mDeployment, mMaxRuntimeBatchSize, loraWeightsMap, stream);
213	        mPipelineIO
214	            = std::make_unique<PipelineIO>(PipelineIO::createForSpecDecode(mDeployment, mMaxRuntimeBatchSize, stream));
215	    }
216	    else
217	    {
218	        mSharedResources = SharedResources::createForLLM(mDeployment.base, loraWeightsMap, stream);
219	        mPipelineIO = std::make_unique<PipelineIO>(PipelineIO::createForLLM(mDeployment.base, stream));
220	    }
221	    // Externalized model weights: the SharedResources factory only allocates an
222	    // empty manager. Load external weights and validate against engine inputs.
223	    // This handles the base engine; the spec-decode draft engine loads its own
224	    // external weights from draft_config.json inside the EAGLE/MTP decoder.
225	    mSharedResources->externalWeightManager->load(std::filesystem::path(engineDir), baseConfigPath, stream);
226	    mSharedResources->externalWeightManager->validateAgainstEngine(*mBaseExecutor, "base");
227	
228	    // -----------------------------------------------------------------------
229	    // 7. Build base TensorMap (kvCacheIndex=0) and publish static external
230	    //    weight bindings. Speculative decoders add tree-mask / position IDs
231	    //    to this same map further down.
232	    // -----------------------------------------------------------------------
233	    buildTensorMap(mBaseTensorMap, *mPipelineIO, *mSharedResources, mDeployment.base, /*kvCacheIndex=*/0);
234	    mSharedResources->externalWeightManager->registerTensorMapEntries(mBaseTensorMap);
235	
236	    // -----------------------------------------------------------------------
237	    // 8. LoRA: register engine bindings and seed the base tensor map with
238	    //    dummy / active adapter tensors. Only the base engine carries LoRA
239	    //    bindings — draft does not.
240	    // -----------------------------------------------------------------------
241	    if (mSharedResources->loraManager)
242	    {
243	        mSharedResources->loraManager->initializeEngineBindings(*mBaseExecutor);
244	        mSharedResources->loraManager->refreshTensorMap(mBaseTensorMap);
245	    }
246	
247	    // -----------------------------------------------------------------------
248	    // 9. Preprocessors.
249	    // -----------------------------------------------------------------------
250	    mStepPreparer = std::make_unique<StepPreparer>(mDeployment.base);
251	    mEmbeddingPre = std::make_unique<EmbeddingPreprocessor>(mEmbedding, mDeployment.base);
252	    if (mDeployment.base.numDeepstackFeatures > 0)
253	    {
254	        mDeepstack = std::make_unique<DeepstackBinding>(mPipelineIO->deepstackEmbeds, mSharedResources->zeroBuffer);
255	    }
256	
257	    // -----------------------------------------------------------------------
258	    // 10. Allocate runtime-local tensors (sampling workspace, host pinned scratch,
259	    //     batch-eviction mapping). Strategy-specific tensors are owned by strategies.
260	    // -----------------------------------------------------------------------
261	    int32_t const effectiveMaxProposalSize = hasDraft ? mDeployment.effectiveMaxDraftProposalSize() : 1;
262	    int32_t const effectiveDraftTopK = hasDraft ? draftingConfig->draftingTopK : 1;
263	    int32_t const maxInputLength = hasDraft
264	        ? std::max(mDeployment.base.maxSupportedInputLength, mDeployment.draft->maxSupportedInputLength)
265	        : mDeployment.base.maxSupportedInputLength;
266	    int32_t const maxSamplingSize = hasDraft ? std::max(mMaxRuntimeBatchSize * effectiveMaxProposalSize,
267	                                                   mMaxRuntimeBatchSize * effectiveDraftTopK * effectiveDraftTopK)
268	                                             : mMaxRuntimeBatchSize;
269	
270	    // Reserve enough workspace for sampling, accounting for batch dimension in draft proposal stage.
271	    // Always include vanilla sampling workspace size because per-request disable_spec_decode
272	    // can fall back to topK/topP sampling even when draft is loaded.
273	    int32_t const vanillaSamplingWorkspaceSize
274	        = static_cast<int32_t>(getTopKtopPSamplingWorkspaceSize(mMaxRuntimeBatchSize, mDeployment.base.outputVocabSize,
275	            SamplingParams(mMaxRuntimeBatchSize, mDeployment.base.outputVocabSize, 1.0f, 0, 0.9f)));
276	    int32_t const draftSamplingRows = hasDraft && mDeployment.specDecodeMode() == SpecDecodeMode::kDFlash
277	        ? mMaxRuntimeBatchSize * mDeployment.specConfig->verifySize
278	        : mMaxRuntimeBatchSize * effectiveDraftTopK;
279	    int32_t const draftSamplingTopK
280	        = hasDraft && mDeployment.specDecodeMode() == SpecDecodeMode::kDFlash ? 1 : effectiveDraftTopK;
281	    mLogprobsMaxBatchDim = mMaxRuntimeBatchSize * mDeployment.maxAcceptedTokensPerRound();
282	    int32_t const logprobsWorkspaceSize = static_cast<int32_t>(
283	        getExtractTopKLogprobsWorkspaceSize(mLogprobsMaxBatchDim, mDeployment.base.outputVocabSize, kMaxLogprobsK));
284	    int32_t const maxSamplingWorkspaceSize = hasDraft
285	        ? std::max({vanillaSamplingWorkspaceSize,
286	              static_cast<int32_t>(
287	                  getSelectAllTopKWorkspaceSize(mMaxRuntimeBatchSize, mDeployment.base.outputVocabSize, 1)),
288	              static_cast<int32_t>(getSelectAllTopKWorkspaceSize(
289	                  draftSamplingRows, mDeployment.draft->outputVocabSize, draftSamplingTopK)),
290	              logprobsWorkspaceSize})
291	        : std::max(vanillaSamplingWorkspaceSize, logprobsWorkspaceSize);
292	
293	    try
294	    {
295	        mIdsInput = rt::Tensor({mMaxRuntimeBatchSize, maxInputLength}, rt::DeviceType::kGPU, DataType::kINT32,
296	            "LLMInferenceRuntime::mIdsInput");
297	
298	        mSamplingWorkspace = rt::Tensor({maxSamplingWorkspaceSize}, rt::DeviceType::kGPU, DataType::kINT8,
299	            "LLMInferenceRuntime::mSamplingWorkspace");
300	        mSamplingIndices = rt::Tensor(
301	            {maxSamplingSize}, rt::DeviceType::kGPU, DataType::kINT32, "LLMInferenceRuntime::mSamplingIndices");
302	        mSamplingScores = rt::Tensor(
303	            {maxSamplingSize}, rt::DeviceType::kGPU, DataType::kFLOAT, "LLMInferenceRuntime::mSamplingScores");
304	        allocateLogitBias(mLogitBias, mMaxRuntimeBatchSize);
305	
306	        // Batch mapping tensor for batch eviction.
307	        mDeviceBatchMapping = rt::Tensor(
308	            {mMaxRuntimeBatchSize}, rt::DeviceType::kGPU, DataType::kINT32, "LLMInferenceRuntime::mDeviceBatchMapping");
309	
310	        mHostPackedTokenIds = rt::Tensor({mMaxRuntimeBatchSize, maxInputLength}, rt::DeviceType::kCPU, DataType::kINT32,
311	            "LLMInferenceRuntime::mHostPackedTokenIds");
312	        mHostSelectedTokenIds = rt::Tensor({mMaxRuntimeBatchSize}, rt::DeviceType::kCPU, DataType::kINT32,
313	            "LLMInferenceRuntime::mHostSelectedTokenIds");
314	        mHostReuseKVCacheLengths = rt::Tensor({mMaxRuntimeBatchSize}, rt::DeviceType::kCPU, DataType::kINT32,
315	            "LLMInferenceRuntime::mHostReuseKVCacheLengths");
316	
317	        // Pre-allocate multimodal indices tensor (used for audio/vision embedding lookup).
318	        mMultimodalIndices = rt::Tensor({mMaxRuntimeBatchSize, maxInputLength}, rt::DeviceType::kGPU, DataType::kINT32,
319	            "LLMInferenceRuntime::mMultimodalIndices");
320	
321	        allocateLogprobsTensors();
322	    }
323	    catch (std::exception const& e)
324	    {
325	        LOG_ERROR("Failed to allocate runtime tensors: %s", e.what());
326	        throw std::runtime_error("Failed to allocate runtime tensors: " + std::string(e.what()));
327	    }
328	    if (mDeployment.base.pleEnabled)
329	    {
330	        int32_t const maxPleSeqLen = std::max(maxInputLength, std::max(1, mDeployment.base.maxVerifyTreeSize));
331	        mGemma4Ple = std::make_unique<Gemma4EmbeddingPreprocessor>(std::filesystem::path(engineDir), mDeployment.base,
332	            mMaxRuntimeBatchSize, maxPleSeqLen, mBaseTensorMap, stream);
333	    }
334	    LOG_INFO("Runtime tensors successfully allocated.");
335	
336	    // -----------------------------------------------------------------------
337	    // 11. Load optional base model reduced-vocab mapping table.
338	    // -----------------------------------------------------------------------
339	    if (mDeployment.base.reducedVocabSize > 0)
340	    {
341	        LOG_INFO("Loading vocabulary mapping table for base model reduced vocab size: %d -> %d",
342	            mDeployment.base.reducedVocabSize, mDeployment.base.vocabSize);
343	        std::filesystem::path const vocabMapPath = std::filesystem::path(engineDir) / binding_names::kVocabMapFileName;
344	
345	        std::vector<rt::Tensor> vocabMapTensors;
346	        ELLM_CHECK(safetensors::loadSafetensors(vocabMapPath, vocabMapTensors, stream),
347	            "Failed to load " + std::string(binding_names::kVocabMapFileName) + " from model directory: " + engineDir);
348	
349	        check::check(vocabMapTensors.size() == 1,
350	            std::string(binding_names::kVocabMapFileName) + " should contain exactly one tensor");
351	        check::check(vocabMapTensors[0].getShape().getNumDims() == 1, "vocab_map tensor should be 1D");
352	        check::check(vocabMapTensors[0].getShape()[0] == mDeployment.base.reducedVocabSize,
353	            "vocab_map tensor length should match base model reduced vocab size");
354	        check::check(vocabMapTensors[0].getDataType() == DataType::kINT32, "vocab_map tensor should be INT32");
355	        mBaseVocabMappingTable = std::move(vocabMapTensors[0]);
356	        setLogitBiasVocabMap(
357	            mLogitBias, mBaseVocabMappingTable, mDeployment.base.vocabSize, mDeployment.base.reducedVocabSize, stream);
358	        LOG_INFO("Base model vocabulary mapping table successfully loaded.");
359	    }
360	
361	    // -----------------------------------------------------------------------
362	    // 12. Tokenizer.
363	    // -----------------------------------------------------------------------
364	    mTokenizer = std::make_unique<tokenizer::Tokenizer>();
365	    LOG_INFO("Start loading tokenizer from model directory: %s", engineDir.c_str());
366	    ELLM_CHECK(mTokenizer->loadFromHF(engineDir), "Failed to load tokenizer from model directory: " + engineDir);
367	    LOG_INFO("Tokenizer successfully loaded from model directory: %s", engineDir.c_str());
368	
369	    // Set additional EOS token IDs from parsed config (e.g. Gemma4 has eos_token_id: [1, 106])
370	    if (!mDeployment.base.eosTokenIds.empty())
371	    {
372	        std::vector<tokenizer::Rank> additionalEos(
373	            mDeployment.base.eosTokenIds.begin(), mDeployment.base.eosTokenIds.end());
374	        mTokenizer->setAdditionalEosIds(additionalEos);
375	        LOG_INFO("Loaded %zu EOS token IDs from config", additionalEos.size());
376	    }
377	
378	    // -----------------------------------------------------------------------
379	    // 13. Decoding strategies.
380	    // -----------------------------------------------------------------------
381	    buildDecodingRuntimeContext();
382	    mDecoderRegistry = std::make_unique<DecoderRegistry>(
383	        *mDecodingRuntimeContext, DecoderRegistryConfig{std::filesystem::path(engineDir), draftingConfig, stream});
384	
385	    // -----------------------------------------------------------------------
386	    // 14. Optional multimodal runners.
387	    // -----------------------------------------------------------------------
388	    if (!multimodalEngineDir.empty())
389	    {
390	        auto tryLoadRunner = [&](std::string const& dir, std::string const& name) -> std::unique_ptr<MultimodalRunner> {
391	            try
392	            {
393	                LOG_DEBUG("Attempting to load %s runner from %s", name.c_str(), dir.c_str());
394	                auto runner = MultimodalRunner::create(
395	                    dir, mDeployment.base.maxSupportedBatchSize, mDeployment.base.maxKVCacheCapacity, stream);
396	                LOG_INFO("%s runner successfully initialized", name.c_str());
397	                return runner;
398	            }
399	            catch (std::exception const& e)
400	            {
401	                LOG_DEBUG("Failed to load %s runner from %s: %s", name.c_str(), dir.c_str(), e.what());
402	                return nullptr;
403	            }
404	        };
405	
406	        mAudioRunner = tryLoadRunner(multimodalEngineDir + "/audio", "Audio");
407	        mVisionRunner = tryLoadRunner(multimodalEngineDir + "/visual", "Visual");
408	        if (!mVisionRunner)
409	        {
410	            mVisionRunner = tryLoadRunner(multimodalEngineDir, "Vision");
411	        }
412	
413	        // At least one multimodal runner must be available
414	        ELLM_CHECK(mAudioRunner || mVisionRunner, "No valid multimodal engine found in " + multimodalEngineDir);
415	
416	        // Try to load action expert from multimodalEngineDir/action
417	        try
418	        {
419	            std::string actionDir = multimodalEngineDir + "/action";
420	            LOG_INFO("Attempting to load Action runner from %s", actionDir.c_str());
421	            mActionRunner = std::make_unique<Alpamayo1ActionRunner>(
422	                actionDir, stream, mSharedResources->cacheManagers[0]->getKVCacheManager().getConfig());
423	            LOG_INFO("Alpamayo 1 action expert loaded.");
424	        }
425	        catch (std::exception const& e)
426	        {
427	            LOG_INFO("Failed to load Action runner from %s: %s", (multimodalEngineDir + "/action").c_str(), e.what());
428	        }
429	
430	        // Validate that the action engine's max KV cache capacity matches the LLM engine's.
431	        if (mActionRunner)
432	        {
433	            int32_t const actionMaxKVCacheCapacity = mActionRunner->getMaxKVCacheCapacity();
434	            int32_t const llmMaxKVCacheCapacity = mDeployment.base.maxKVCacheCapacity;
435	            ELLM_CHECK(actionMaxKVCacheCapacity == llmMaxKVCacheCapacity,
436	                format::fmtstr(
437	                    "Action engine max_kv_cache_capacity (%d) does not match LLM engine max_kv_cache_capacity (%d). "
438	                    "Re-export and rebuild the action engine with --max_kv_cache_capacity=%d to match the LLM engine.",
439	                    actionMaxKVCacheCapacity, llmMaxKVCacheCapacity, llmMaxKVCacheCapacity));
440	        }
441	    }
442	
443	    // -----------------------------------------------------------------------
444	    // 15. Shared execution context memory for all engines (base, optional
445	    //     draft, and optional vision/audio). All engines execute serially so
446	    //     they can share a single buffer sized to the max requirement.
447	    // -----------------------------------------------------------------------
448	    int64_t const baseContextMemorySize = mBaseExecutor->getRequiredContextMemorySize();
449	    int64_t const strategyContextMemorySize = mDecoderRegistry ? mDecoderRegistry->getRequiredContextMemorySize() : 0;
450	    int64_t const visionContextMemorySize = mVisionRunner ? mVisionRunner->getRequiredContextMemorySize() : 0;
451	    int64_t const audioContextMemorySize = mAudioRunner ? mAudioRunner->getRequiredContextMemorySize() : 0;
452	    int64_t const actionContextMemorySize = mActionRunner ? mActionRunner->getRequiredContextMemorySize() : 0;
453	    int64_t const sharedContextMemorySize = std::max({baseContextMemorySize, strategyContextMemorySize,
454	        visionContextMemorySize, audioContextMemorySize, actionContextMemorySize});
455	    mSharedExecContextMemory = rt::Tensor({sharedContextMemorySize}, rt::DeviceType::kGPU, nvinfer1::DataType::kUINT8,
456	        "LLMInferenceRuntime::mSharedExecContextMemory");
457	    mBaseExecutor->setContextMemory(mSharedExecContextMemory);
458	    if (mDecoderRegistry)
459	    {
460	        mDecoderRegistry->setContextMemory(mSharedExecContextMemory);
461	    }
462	    if (mVisionRunner)
463	    {
464	        mVisionRunner->setContextMemory(mSharedExecContextMemory);
465	    }
466	    if (mAudioRunner)
467	    {
468	        mAudioRunner->setContextMemory(mSharedExecContextMemory);
469	    }
470	    if (mActionRunner)
471	    {
472	        mActionRunner->setContextMemory(mSharedExecContextMemory);
473	    }
474	    LOG_INFO(
475	        "Setup shared execution context memory: %zu bytes (base requires: %zu, strategy requires: %zu, vision "
476	        "requires: "
477	        "%zu, audio requires: %zu, action requires: %zu)",
478	        static_cast<size_t>(sharedContextMemorySize), static_cast<size_t>(baseContextMemorySize),
479	        static_cast<size_t>(strategyContextMemorySize), static_cast<size_t>(visionContextMemorySize),
480	        static_cast<size_t>(audioContextMemorySize), static_cast<size_t>(actionContextMemorySize));
481	}
