483	void LLMInferenceRuntime::allocateLogprobsTensors()
484	{
485	    int32_t const logprobsRows = mMaxRuntimeBatchSize * mDeployment.maxAcceptedTokensPerRound();
486	    mDeviceLogprobsValues = rt::Tensor({logprobsRows, kMaxLogprobsK}, rt::DeviceType::kGPU, DataType::kFLOAT,
487	        "LLMInferenceRuntime::mDeviceLogprobsValues");
488	    mDeviceLogprobsIndices = rt::Tensor({logprobsRows, kMaxLogprobsK}, rt::DeviceType::kGPU, DataType::kINT32,
489	        "LLMInferenceRuntime::mDeviceLogprobsIndices");
490	    mHostLogprobsValues = rt::Tensor({logprobsRows, kMaxLogprobsK}, rt::DeviceType::kCPU, DataType::kFLOAT,
491	        "LLMInferenceRuntime::mHostLogprobsValues");
492	    mHostLogprobsIndices = rt::Tensor({logprobsRows, kMaxLogprobsK}, rt::DeviceType::kCPU, DataType::kINT32,
493	        "LLMInferenceRuntime::mHostLogprobsIndices");
494	    if (mDeployment.specConfig.has_value())
495	    {
496	        mGatheredLogits = rt::Tensor({logprobsRows, mDeployment.base.outputVocabSize}, rt::DeviceType::kGPU,
497	            DataType::kFLOAT, "LLMInferenceRuntime::mGatheredLogits");
498	    }
499	}
