501	void LLMInferenceRuntime::buildDecodingRuntimeContext()
502	{
503	    BaseEngineResources baseResources{*mBaseExecutor, mBaseTensorMap, *mSharedResources,
504	        *mSharedResources->cacheManagers[0], *mPipelineIO, [this](InferenceDims const& dims, cudaStream_t stream) {
505	            return captureBaseGraphWithLoraFanout(dims, stream);
506	        }};
507	    PreprocessResources preprocessResources{
508	        *mStepPreparer, *mEmbeddingPre, mEmbedding, mIdsInput, mDeepstack.get(), mGemma4Ple.get()};
509	    SamplingBuffers sampling{mSamplingWorkspace, mSamplingIndices, mSamplingScores, mBaseVocabMappingTable,
510	        mHostPackedTokenIds, mHostSelectedTokenIds};
511	    LogprobsBuffers logprobs{
512	        mDeviceLogprobsValues, mDeviceLogprobsIndices, mHostLogprobsValues, mHostLogprobsIndices, mGatheredLogits};
513	    mDecodingRuntimeContext.reset(new DecodingRuntimeContext{mDeployment, mMaxRuntimeBatchSize, baseResources,
514	        preprocessResources, *mTokenizer, mLogitBias, sampling, logprobs});
515	}
