1106	            LOG_ERROR("Alpamayo1ActionRunner trajectory sampling failed.");
1107	            return false;
1108	        }
1109	        for (size_t i = 0; i < trajectories.size() && i < static_cast<size_t>(activeBatchSize); ++i)
