1121	bool LLMInferenceRuntime::validateRequestConfig(LLMGenerationRequest const& request)
1122	{
1123	    int32_t const activeBatchSize = static_cast<int32_t>(request.requests.size());
1124	    bool const hasAudio = std::any_of(
1125	        request.requests.begin(), request.requests.end(), [](auto const& req) { return !req.audioBuffers.empty(); });
1126	    bool const hasVision = std::any_of(
1127	        request.requests.begin(), request.requests.end(), [](auto const& req) { return !req.imageBuffers.empty(); });
1128	    bool const hasTrajectoryHistory = std::any_of(request.requests.begin(), request.requests.end(),
1129	        [](auto const& req) { return req.pastTrajectory.has_value(); });
1130	
1131	    if (activeBatchSize == 0)
1132	    {
1133	        LOG_ERROR("Empty request with no requests");
1134	        return false;
1135	    }
1136	
1137	    if (activeBatchSize > mMaxRuntimeBatchSize)
1138	    {
1139	        LOG_ERROR(
1140	            "Requested batch size %d exceeds maximum supported batch size %d", activeBatchSize, mMaxRuntimeBatchSize);
1141	        return false;
1142	    }
1143	    for (int32_t i = 0; i < activeBatchSize; ++i)
1144	    {
1145	        if (request.requests[i].messages.empty())
1146	        {
1147	            LOG_ERROR("Request %d in batch is empty: no messages provided", i);
1148	            return false;
1149	        }
