1160	            {
1161	                LOG_ERROR("Request %d logit_bias token ID %d is outside the full vocabulary range [0, %d)", i, tokenId,
1162	                    mDeployment.base.vocabSize);
1163	                return false;
1164	            }
1165	            if (!std::isfinite(bias) || bias < limits::security::kMinLogitBias
1166	                || bias > limits::security::kMaxLogitBias)
1167	            {
1168	                LOG_ERROR("Request %d logit_bias for token ID %d must be finite and in [%.1f, %.1f], got %.6f", i,
