1176	    {
1177	        LOG_ERROR(
1178	            "logit_bias is not supported while speculative decoding is enabled; set disable_spec_decode=true or use "
1179	            "a vanilla engine.");
1180	        return false;
1181	    }
1182	    if (hasAudio && !mAudioRunner)
1183	    {
1184	        LOG_ERROR("Request contains audio input, but this runtime does not have an audio runner.");
1185	        return false;
1186	    }
1187	    if (hasVision && !mVisionRunner)
1188	    {
1189	        LOG_ERROR("Request contains vision input, but this runtime does not have a vision runner.");
1190	        return false;
1191	    }
1192	    if (hasTrajectoryHistory && !mActionRunner)
1193	    {
1194	        LOG_ERROR("Request contains trajectory history input, but this runtime does not have an action runner.");
1195	        return false;
1196	    }
1197	    if (mDeployment.base.useVisionBidirectionalAttention && request.saveSystemPromptKVCache)
1198	    {
1199	        LOG_ERROR("System-prompt KV-cache reuse is not supported with Gemma4 vision bidirectional attention.");
1200	        return false;
1201	    }
1202	
1203	    return true;
1204	}
1205	
1206	bool LLMInferenceRuntime::multiModalRuntimePreprocess(
1207	    LLMGenerationRequest const& request, DecodingInferenceContext& context, cudaStream_t stream)
1208	{
1209	    int32_t const activeBatchSize = static_cast<int32_t>(request.requests.size());
1210	    bool const hasAudio = std::any_of(
1211	        request.requests.begin(), request.requests.end(), [](auto const& req) { return !req.audioBuffers.empty(); });
1212	    bool const hasVision = std::any_of(
1213	        request.requests.begin(), request.requests.end(), [](auto const& req) { return !req.imageBuffers.empty(); });
1214	    bool const hasTrajectoryHistory = std::any_of(request.requests.begin(), request.requests.end(),
1215	        [](auto const& req) { return req.pastTrajectory.has_value(); });
1216	
1217	    // Clear request-scoped multimodal state up front so previous requests cannot leak through reused runtime members.
1218	    context.visualEmbeddings = std::nullopt;
1219	    context.audioEmbeddings = std::nullopt;
1220	    context.deepstackFeatures.clear();
1221	    // Treat multimodal indices as request-scoped state. Only request paths that explicitly rebuild
1222	    // mMultimodalIndices for the current request should observe a non-empty tensor downstream.
1223	    check::check(mMultimodalIndices.reshape({0}), "Tensor reshape failed");
1224	
1225	    // Mark multimodal preprocessing and inference for NVTX profiling
1226	    NVTX_SCOPED_RANGE(nvtx_multimodal, "MULTIMODAL_PROCESSING", nvtx_colors::ORANGE);
1227	
1228	    std::vector<std::vector<int32_t>> batchedInputIds;
1229	
1230	    // MRope cos/sin output cache is supplied only for MRope-based runners (QwenViT, Qwen3OmniAudio).
1231	    // Runners with standard RoPE (InternViT, Phi4MMViT) ignore it; see MultimodalRunner::preprocess.
1232	    rt::OptionalOutputTensor mropeCosSinOut = (mDeployment.base.ropeConfig.type == RopeType::kMRope)
1233	        ? rt::OptionalOutputTensor{std::ref(mPipelineIO->mropeCosSin)}
1234	        : std::nullopt;
1235	
1236	    // Process audio inputs (if present)
1237	    if (hasAudio && mAudioRunner)
1238	    {
1239	        LOG_INFO("Processing audio inputs");
1240	        if (!mAudioRunner->preprocess(request, batchedInputIds, mTokenizer.get(), mropeCosSinOut, stream))
1241	        {
1242	            LOG_ERROR("Audio preprocessing failed. This request cannot be handled.");
1243	            return false;
1244	        }
1245	
1246	        if (!mAudioRunner->infer(stream))
1247	        {
1248	            LOG_ERROR("Audio inference failed. This request cannot be handled.");
1249	            return false;
1250	        }
1251	    }
1252	
1253	    // Process vision inputs (if present)
1254	    if (hasVision && mVisionRunner)
1255	    {
1256	        LOG_INFO("Processing vision inputs");
1257	        if (!mVisionRunner->preprocess(request, batchedInputIds, mTokenizer.get(), mropeCosSinOut, stream))
1258	        {
1259	            LOG_ERROR("Vision preprocessing failed. This request cannot be handled.");
1260	            return false;
1261	        }
1262	
1263	        if (!mVisionRunner->infer(stream))
1264	        {
1265	            LOG_ERROR("Vision inference failed. This request cannot be handled.");
1266	            return false;
1267	        }
1268	    }
1269	
1270	    // Process action inputs (if present)
1271	    if (hasTrajectoryHistory && mActionRunner)
1272	    {
1273	        LOG_INFO("Processing trajectory history inputs");
1274	        if (!mActionRunner->preprocess(request, batchedInputIds, mTokenizer.get()))
1275	        {
1276	            LOG_ERROR(
1277	                "LLMInferenceRuntime(): Trajectory history preprocessing failed. This request cannot be handled.");
1278	            return false;
1279	        }
1280	    }
1281	
1282	    if (!hasAudio && !hasVision)
1283	    {
1284	        for (int32_t i = 0; i < activeBatchSize; ++i)
1285	        {
1286	            batchedInputIds.push_back(mTokenizer->encode(request.formattedRequests[i].formattedCompleteRequest, false));
1287	            if (batchedInputIds.back().empty())
1288	            {
1289	                LOG_ERROR("Failed to tokenize input text for request %d in batch", i);
1290	                return false;
1291	            }
1292	        }
1293	        if (mDeployment.base.ropeConfig.type == RopeType::kMRope)
1294	        {
1295	            rt::Tensor& ropeCosSinCache = mPipelineIO->mropeCosSin;
1296	            check::check(ropeCosSinCache.reshape({mDeployment.base.maxSupportedBatchSize,
1297	                             mDeployment.base.maxKVCacheCapacity, mDeployment.base.rotaryDim}),
1298	                "Tensor reshape failed");
1299	            kernel::initializeTextOnlyMRopeCosSin(ropeCosSinCache.dataPointer<float>(),
1300	                mDeployment.base.ropeConfig.rotaryTheta, mDeployment.base.rotaryDim,
1301	                mDeployment.base.maxKVCacheCapacity, mDeployment.base.maxSupportedBatchSize, stream);
1302	        }
1303	    }
1304	
1305	    // Get embeddings from independent runners — gate on request having multimodal data,
1306	    // not just runner existence, to avoid leaking stale embeddings from previous requests.
1307	    rt::OptionalInputTensor visionEmbeddings
1308	        = (hasVision && mVisionRunner) ? std::optional{std::ref(mVisionRunner->getOutputEmbedding())} : std::nullopt;
1309	    rt::OptionalInputTensor audioEmbeddings
1310	        = (hasAudio && mAudioRunner) ? std::optional{std::ref(mAudioRunner->getOutputEmbedding())} : std::nullopt;
1311	    rt::OptionalInputTensors deepstackFeatures
1312	        = (hasVision && mVisionRunner) ? mVisionRunner->getDeepstackFeatures() : rt::OptionalInputTensors{};
1313	
1314	    context.visualEmbeddings = visionEmbeddings;
1315	    context.deepstackFeatures = deepstackFeatures;
1316	    context.audioEmbeddings = audioEmbeddings;
1317	
1318	    // Populate system prompts and raw input IDs from batchedInputIds
1319	    for (int32_t i = 0; i < activeBatchSize; ++i)
1320	    {
1321	        context.systemPrompts[i] = request.formattedRequests[i].formattedSystemPrompt;
1322	        context.rawBatchedInputIds.push_back(batchedInputIds[i]);
1323	    }
1324	
1325	    return true;
1326	}
1327	
1328	bool LLMInferenceRuntime::runBaseModelPrefill(DecodingInferenceContext& context)
1329	{
1330	    TIME_STAGE(metrics::StageNames::kLLM_PREFILL, context.stream);
1331	    NVTX_SCOPED_RANGE(nvtx_base_prefill,
1332	        ("SPEC_DECODE_BASE_PREFILL[" + std::to_string(context.activeBatchSize) + "]").c_str(), nvtx_colors::BLUE);
1333	
1334	    int32_t const activeBatchSize = context.activeBatchSize;
1335	    int32_t const inputIdsLength
1336	        = *std::max_element(context.effectivePrefillLengths.begin(), context.effectivePrefillLengths.end());
1337	    int32_t const baseOutputHiddenDim
1338	        = mDeployment.specConfig.has_value() ? mDeployment.specConfig->baseOutputHiddenDim : 0;
1339	
1340	    // Reshape IO tensors for this step.
1341	    check::check(mIdsInput.reshape({activeBatchSize, inputIdsLength}), "Tensor reshape failed");
1342	    check::check(mPipelineIO->hostContextLengths.reshape({activeBatchSize}), "Tensor reshape failed");
1343	    check::check(mPipelineIO->inputsEmbeds.reshape({activeBatchSize, inputIdsLength, mDeployment.base.hiddenSize}),
1344	        "Tensor reshape failed");
1345	    check::check(mPipelineIO->outputLogits.reshape({activeBatchSize, mDeployment.base.outputVocabSize}),
1346	        "Tensor reshape failed");
1347	    if (mDeployment.specConfig.has_value())
1348	    {
1349	        // SpecDecode base engines emit target features that feed the draft engine.
1350	        check::check(mPipelineIO->baseHiddenStates.reshape({activeBatchSize, inputIdsLength, baseOutputHiddenDim}),
1351	            "Tensor reshape failed");
1352	    }
1353	
1354	    // Populate host-side context lengths with effective (unpadded) prefill lengths and pack tokens.
1355	    int32_t* hostCtxLenData = mPipelineIO->hostContextLengths.dataPointer<int32_t>();
1356	    check::check(mHostPackedTokenIds.reshape({activeBatchSize, inputIdsLength}), "Tensor reshape failed");
1357	    int32_t* hostPackedTokenIdsData = mHostPackedTokenIds.dataPointer<int32_t>();
1358	
1359	    // Clear the entire pinned buffer first so trailing pad slots from prior batches don't leak into the
1360	    // multimodal-indices walk, which scans all inputIdsLength positions per row, not just up to context_length.
1361	    std::fill(hostPackedTokenIdsData, hostPackedTokenIdsData + activeBatchSize * inputIdsLength, 0);
1362	
1363	    for (int32_t i = 0; i < activeBatchSize; ++i)
1364	    {
1365	        hostCtxLenData[i] = context.effectivePrefillLengths[i];
1366	        std::copy(context.tokenIds[i].begin(), context.tokenIds[i].end(), hostPackedTokenIdsData + i * inputIdsLength);
1367	    }
1368	
1369	    CUDA_CHECK(cudaMemcpyAsync(mIdsInput.rawPointer(), hostPackedTokenIdsData,
1370	        activeBatchSize * inputIdsLength * sizeof(int32_t), cudaMemcpyHostToDevice, context.stream));
1371	
1372	    bool const baseKVAllEmpty = mSharedResources->cacheManagers[0]->getKVCacheAllEmpty();
1373	    if (mDeployment.base.useVisionBidirectionalAttention)
1374	    {
1375	        // Vision-block attention supports only non-chunked prefill. Decode
1376	        // ignores this binding and uses causal decode attention over the
1377	        // canonical KV cache.
1378	        if (!baseKVAllEmpty)
1379	        {
1380	            LOG_ERROR(
1381	                "Gemma4 vision bidirectional attention does not yet support prefix-cache reuse or chunked prefill.");
1382	            return false;
1383	        }
1384	        check::check(mPipelineIO->visionBlockIds.reshape({activeBatchSize, inputIdsLength}), "Tensor reshape failed");
1385	        rt::Tensor hostVisionBlockIds = generateVisionBlockIds(mHostPackedTokenIds, mDeployment.base.imageTokenId);
1386	        // hostVisionBlockIds owns short-lived pinned storage. Keep this copy
1387	        // synchronous so the source remains alive until H2D completion.
1388	        CUDA_CHECK(cudaMemcpy(mPipelineIO->visionBlockIds.rawPointer(), hostVisionBlockIds.rawPointer(),
1389	            activeBatchSize * inputIdsLength * sizeof(int32_t), cudaMemcpyHostToDevice));
1390	    }
1391	
1392	    // Embedding lookup (text / vision / audio-multimodal) into mPipelineIO->inputsEmbeds;
1393	    // deepstack slots are populated from features or zero-filled depending on the request.
1394	    mEmbeddingPre->embed(mIdsInput, context.visualEmbeddings, context.audioEmbeddings, *mPipelineIO, context.stream);
1395	    mEmbeddingPre->prepareDeepstack(mIdsInput, context.deepstackFeatures, *mPipelineIO, context.stream);
1396	    if (mGemma4Ple)
1397	    {
1398	        mGemma4Ple->embed(mIdsInput, context.stream);
1399	    }
1400	
1401	    // Dispatch per-step sequence prep (context lengths H2D, selectTokenIndices).
1402	    mStepPreparer->prepare(
1403	        InferencePhase::kPrefill, activeBatchSize, *mSharedResources->cacheManagers[0], *mPipelineIO, context.stream);
1404	    // Bind real deepstack features for this prefill (no-op when feature absent).
1405	    if (mDeepstack)
1406	    {
1407	        mDeepstack->useRealFeatures(mBaseTensorMap);
1408	    }
1409	
1410	    // Execute base prefill through the EngineExecutor. Empty-cache is
1411	    // runtime-dynamic; prefillDims uses it to set InferenceDims::startIndexLen
1412	    // (0 for the "initial prefill" sentinel, else batch).
1413	    auto const prefillDims = mDeployment.base.prefillDims(activeBatchSize, inputIdsLength, baseKVAllEmpty);
1414	
1415	    check::check(mBaseExecutor->prepare(kPrefillProfile, prefillDims, mBaseTensorMap, context.stream),
1416	        "Failed to prepare base model for prefill step.");
1417	    check::check(mBaseExecutor->execute(context.stream), "Failed to execute base model for prefill step.");
1418	    mSharedResources->cacheManagers[0]->commitSequenceLength(mPipelineIO->contextLengths, context.stream);
1419	
1420	    applyLogitBias(mLogitBias, mPipelineIO->outputLogits, context, context.stream);
1421	
1422	    // Sampling from the prefill stage logits follows the same policy as vanilla decoding.
1423	    // Speculative decoders reach this code with greedy-compatible context params because
1424	    // handleRequest normalizes active spec-decode requests before decoding.
1425	    check::check(mSamplingIndices.reshape({activeBatchSize, 1}), "Tensor reshape failed");
1426	    if (shouldUseNonGreedySampling(context.temperature, context.topK, context.topP))
1427	    {
1428	        SamplingParams params(activeBatchSize, mDeployment.base.outputVocabSize, context.temperature,
1429	            static_cast<int32_t>(context.topK), context.topP);
1430	        topKtopPSamplingFromLogits(
1431	            mPipelineIO->outputLogits, mSamplingIndices, params, mSamplingWorkspace, context.stream);
1432	    }
1433	    else
1434	    {
1435	        constexpr int32_t kSAMPLING_TOP_K = 1;
1436	        selectAllTopK(mPipelineIO->outputLogits, std::nullopt, mSamplingIndices, kSAMPLING_TOP_K, mSamplingWorkspace,
1437	            context.stream);
1438	    }
1439	
1440	    // Apply vocabulary mapping if base model uses reduced vocabulary.
1441	    if (mDeployment.base.reducedVocabSize > 0)
1442	    {
1443	        mapReducedVocabToFullVocab(mSamplingIndices, mBaseVocabMappingTable, context.stream);
1444	    }
1445	
1446	    // Enqueue logprobs extraction + D2H before the round's single synchronization so the
1447	    // copies ride the same sync as the sampled-token D2H below.
1448	    if (context.numLogprobs > 0)
1449	    {
1450	        decoder_utils::enqueueLogprobsD2H(mDecodingRuntimeContext->base.pipelineIO.outputLogits, activeBatchSize,
1451	            *mDecodingRuntimeContext, context.numLogprobs, context.stream);
1452	    }
1453	
1454	    check::check(mHostSelectedTokenIds.reshape({activeBatchSize}), "Tensor reshape failed");
1455	    int32_t* hostSelectedTokenIdsData = mHostSelectedTokenIds.dataPointer<int32_t>();
1456	    CUDA_CHECK(cudaMemcpyAsync(hostSelectedTokenIdsData, mSamplingIndices.rawPointer(),
1457	        activeBatchSize * sizeof(int32_t), cudaMemcpyDeviceToHost, context.stream));
1458	    CUDA_CHECK(cudaStreamSynchronize(context.stream));
1459	
1460	    // Few-layer-validation debug: dump round 0 (prefill). At this point the KV cache is committed and
1461	    // tokenIds[i].size() == the prefill length == the committed cache length.
1462	    if (context.layerDebugger != nullptr)
1463	    {
1464	        std::vector<int32_t> validLengths(activeBatchSize);
1465	        for (int32_t i = 0; i < activeBatchSize; ++i)
1466	        {
1467	            validLengths[i] = static_cast<int32_t>(context.tokenIds[i].size());
1468	        }
1469	        context.layerDebugger->dumpRound(*mSharedResources->cacheManagers[0], mPipelineIO->outputLogits, validLengths,
1470	            hostSelectedTokenIdsData, activeBatchSize, context.stream);
1471	
1472	        // Teacher-forcing — feed the golden's tokens instead of our own sampled ones (no-op unless
1473	        // EDGELLM_FORCE_TOKENS_FILE is set). Applied after the dump so the dump still records what we
1474	        // *would* have sampled; the pushed token below is the forced one.
1475	        context.layerDebugger->applyForcedTokens(
1476	            context.currentGenerateLengths, hostSelectedTokenIdsData, activeBatchSize);
1477	    }
1478	
1479	    for (int32_t i = 0; i < activeBatchSize; ++i)
1480	    {
1481	        if (!context.finishedStates[i])
1482	        {
1483	            context.tokenIds[i].push_back(hostSelectedTokenIdsData[i]);
1484	            context.currentGenerateLengths[i] += 1;
1485	        }
1486	    }
1487	
1488	    if (context.numLogprobs > 0)
1489	    {
1490	        decoder_utils::collectLogprobsFromHost(*mDecodingRuntimeContext, context, activeBatchSize, context.numLogprobs);
1491	    }
1492	
1493	    emitTokenCallbacks(context);
1494	    return true;
1495	}
