1497	bool LLMInferenceRuntime::captureBaseGraphWithLoraFanout(InferenceDims const& dims, cudaStream_t stream)
1498	{
1499	    auto captureOnce = [&](std::string const& loraName) -> bool {
1500	        if (mSharedResources->loraManager)
1501	        {
1502	            if (loraName.empty())
1503	            {
1504	                mSharedResources->loraManager->resetWeights();
1505	            }
1506	            else
1507	            {
1508	                mSharedResources->loraManager->switchWeights(loraName);
1509	            }
1510	            mSharedResources->loraManager->refreshTensorMap(mBaseTensorMap);
1511	        }
1512	        if (!mBaseExecutor->prepare(kDecodeProfile, dims, mBaseTensorMap, stream))
1513	        {
1514	            return false;
1515	        }
1516	        return mBaseExecutor->captureGraph(stream);
1517	    };
1518	
1519	    bool ok = captureOnce(mEmptyLoraWeightsName);
1520	    if (mDeployment.base.maxSupportedLoraRank > 0 && mSharedResources->loraManager)
1521	    {
1522	        for (auto const& loraWeightsName : mSharedResources->loraManager->getAdapterNames())
1523	        {
1524	            ok &= captureOnce(loraWeightsName);
1525	        }
1526	    }
1527	    return ok;
1528	}
