1550	void LLMInferenceRuntime::restoreRecurrentStates(
1551	    int32_t batchIdx, SystemPromptKVCache const& cachedStates, cudaStream_t stream)
1552	{
1553	    auto& cacheMgrBase = *mSharedResources->cacheManagers[0];
1554	    auto& mambaMgr = cacheMgrBase.getMambaCacheManager();
1555	    auto const& mambaConfig = mambaMgr.getConfig();
1556	
1557	    size_t const recurrentElemSize = rt::utils::getTypeSize(mambaConfig.recurrentStateType);
1558	    size_t const convElemSize = rt::utils::getTypeSize(mambaConfig.convStateType);
1559	    size_t const recurrentBatchBytes = static_cast<size_t>(mambaConfig.recurrentStateNumHeads
1560	                                           * mambaConfig.recurrentStateHeadDim * mambaConfig.recurrentStateSize)
1561	        * recurrentElemSize;
1562	    size_t const convBatchBytes = static_cast<size_t>(mambaConfig.convDim * mambaConfig.convKernel) * convElemSize;
1563	
1564	    for (int32_t layer = 0; layer < mambaMgr.numLayers(); ++layer)
1565	    {
1566	        rt::Tensor& recurrentLayer = mambaMgr.getRecurrentState(layer);
1567	        rt::Tensor& convLayer = mambaMgr.getConvState(layer);
1568	
1569	        auto* recurrentDst = static_cast<std::byte*>(recurrentLayer.rawPointer()) + batchIdx * recurrentBatchBytes;
1570	        auto* convDst = static_cast<std::byte*>(convLayer.rawPointer()) + batchIdx * convBatchBytes;
1571	
1572	        if (layer < static_cast<int32_t>(cachedStates.recurrentStateContents.size()))
1573	        {
1574	            CUDA_CHECK(cudaMemcpyAsync(recurrentDst, cachedStates.recurrentStateContents[layer].rawPointer(),
1575	                recurrentBatchBytes, cudaMemcpyDeviceToDevice, stream));
1576	        }
1577	        else
1578	        {
1579	            CUDA_CHECK(cudaMemsetAsync(recurrentDst, 0, recurrentBatchBytes, stream));
1580	        }
1581	
1582	        if (layer < static_cast<int32_t>(cachedStates.convStateContents.size()))
1583	        {
1584	            CUDA_CHECK(cudaMemcpyAsync(convDst, cachedStates.convStateContents[layer].rawPointer(), convBatchBytes,
1585	                cudaMemcpyDeviceToDevice, stream));
1586	        }
1587	        else
1588	        {
1589	            CUDA_CHECK(cudaMemsetAsync(convDst, 0, convBatchBytes, stream));
1590	        }
1591	    }
1592	}
