1594	void LLMInferenceRuntime::zeroRecurrentStates(int32_t batchIdx, cudaStream_t stream)
1595	{
1596	    auto& cacheMgrBase = *mSharedResources->cacheManagers[0];
1597	    auto& mambaMgr = cacheMgrBase.getMambaCacheManager();
1598	    auto const& mambaConfig = mambaMgr.getConfig();
1599	
1600	    size_t const recurrentElemSize = rt::utils::getTypeSize(mambaConfig.recurrentStateType);
1601	    size_t const convElemSize = rt::utils::getTypeSize(mambaConfig.convStateType);
1602	    size_t const recurrentBatchBytes = static_cast<size_t>(mambaConfig.recurrentStateNumHeads
1603	                                           * mambaConfig.recurrentStateHeadDim * mambaConfig.recurrentStateSize)
1604	        * recurrentElemSize;
1605	    size_t const convBatchBytes = static_cast<size_t>(mambaConfig.convDim * mambaConfig.convKernel) * convElemSize;
1606	
1607	    for (int32_t layer = 0; layer < mambaMgr.numLayers(); ++layer)
1608	    {
1609	        rt::Tensor& recurrentLayer = mambaMgr.getRecurrentState(layer);
1610	        rt::Tensor& convLayer = mambaMgr.getConvState(layer);
1611	
1612	        auto* recurrentDst = static_cast<std::byte*>(recurrentLayer.rawPointer()) + batchIdx * recurrentBatchBytes;
1613	        auto* convDst = static_cast<std::byte*>(convLayer.rawPointer()) + batchIdx * convBatchBytes;
1614	        CUDA_CHECK(cudaMemsetAsync(recurrentDst, 0, recurrentBatchBytes, stream));
1615	        CUDA_CHECK(cudaMemsetAsync(convDst, 0, convBatchBytes, stream));
1616	    }
1617	}
1618	
1619	bool LLMInferenceRuntime::setUpForPrefillExecution(DecodingInferenceContext& context, DecodingStrategy& strategy)
1620	{
1621	    NVTX_SCOPED_RANGE(nvtx_setup, "SETUP_PREFILL_EXECUTION", nvtx_colors::PALE_GREEN);
1622	
1623	    // LoRA switching goes through the LoRAManager on SharedResources.
1624	    if (mDeployment.base.maxSupportedLoraRank > 0 && mSharedResources->loraManager)
1625	    {
1626	        try
1627	        {
1628	            if (context.loraWeightsName.empty())
1629	            {
1630	                mSharedResources->loraManager->resetWeights();
1631	            }
1632	            else
1633	            {
1634	                mSharedResources->loraManager->switchWeights(context.loraWeightsName);
1635	            }
1636	            mSharedResources->loraManager->refreshTensorMap(mBaseTensorMap);
1637	        }
1638	        catch (std::exception const& e)
1639	        {
1640	            LOG_ERROR("Failed to switch LoRA weights to %s: %s", context.loraWeightsName.c_str(), e.what());
1641	            return false;
1642	        }
1643	    }
1644	
1645	    int32_t const activeBatchSize = context.activeBatchSize;
1646	    std::vector<std::vector<int32_t>> const& batchedInputIds = context.rawBatchedInputIds;
1647	    bool const needsStrategyKVCache = strategy.isSpeculative();
1648	    auto& cacheMgrBase = *mSharedResources->cacheManagers[0];
1649	
1650	    // Record the length of the reused KVCache for each sequence.
1651	    check::check(mHostReuseKVCacheLengths.reshape({activeBatchSize}), "Tensor reshape failed");
1652	    int32_t* reuseKVCacheLengthsData = mHostReuseKVCacheLengths.dataPointer<int32_t>();
1653	    std::fill(reuseKVCacheLengthsData, reuseKVCacheLengthsData + activeBatchSize, 0);
1654	
1655	    context.tokenIds.clear();
1656	    context.tokenIds.resize(activeBatchSize);
1657	
1658	    for (int32_t i = 0; i < activeBatchSize; ++i)
1659	    {
1660	        auto const& prompt = context.systemPrompts[i];
1661	        auto const promptKey = keySystemPromptWithLoraWeights(prompt, context.loraWeightsName);
1662	        if (mSystemPromptKVCacheBase.count(promptKey) > 0)
1663	        {
1664	            auto& precachedKVCacheBase = mSystemPromptKVCacheBase[promptKey];
1665	            auto const& kvCacheLayersBase = precachedKVCacheBase.kvCacheLayers;
1666	            cacheMgrBase.restoreKVCache(kvCacheLayersBase, i, context.stream);
1667	
1668	            if (needsStrategyKVCache)
1669	            {
1670	                check::check(strategy.hasSystemPromptKVCache(promptKey),
1671	                    "System prompt cache inconsistency between base and active decoding strategy");
1672	                strategy.restoreSystemPromptKVCache(promptKey, i, context.stream);
1673	            }
1674	
1675	            // Restore recurrent/conv states for hybrid models (vanilla path only — spec decode handles this in
1676	            // decoder).
1677	            if (mDeployment.base.numLinearAttnLayers > 0)
1678	            {
1679	                restoreRecurrentStates(i, precachedKVCacheBase, context.stream);
1680	            }
1681	
1682	            // Per-layer saved KV tensor shape is [2, numKVHeads, sequenceLength, headDim]; shape[2] == seqLen.
1683	            check::check(!kvCacheLayersBase.empty(), "System prompt KV cache must have at least one layer.");
1684	            auto reuseLength = math::cast<size_t>(kvCacheLayersBase[0].getShape()[2]);
1685	            check::check(reuseLength > 0 && reuseLength < batchedInputIds[i].size(),
1686	                "The reuse length shall be larger than 0 and not exceed the input length.");
1687	            // Reuse N-1 tokens from the cached prefix so the Nth token is treated as real input in prefill;
1688	            // this keeps the draft prefill boundary aligned with the true next-token position.
1689	            auto const effectiveReuseLength = reuseLength - 1;
1690	            reuseKVCacheLengthsData[i] = math::cast<int32_t>(effectiveReuseLength);
1691	
1692	            context.tokenIds[i].assign(batchedInputIds[i].begin() + effectiveReuseLength, batchedInputIds[i].end());
1693	            context.effectivePrefillLengths[i] = math::cast<int32_t>(batchedInputIds[i].size() - effectiveReuseLength);
1694	
1695	            bool const matchIds = std::equal(precachedKVCacheBase.tokenizedPrompt.begin(),
1696	                precachedKVCacheBase.tokenizedPrompt.end(), batchedInputIds[i].begin());
1697	            if (!matchIds)
1698	            {
1699	                LOG_WARNING(
1700	                    "Though system prompt strings are matched, token_ids are not perfectly aligned."
1701	                    "This may generate incorrect result, please check your system prompt design.");
1702	            }
1703	        }
1704	        else
1705	        {
1706	            context.tokenIds[i] = batchedInputIds[i];
1707	            context.effectivePrefillLengths[i] = static_cast<int32_t>(batchedInputIds[i].size());
1708	            reuseKVCacheLengthsData[i] = 0;
1709	
1710	            if (mDeployment.base.numLinearAttnLayers > 0)
1711	            {
1712	                zeroRecurrentStates(i, context.stream);
1713	            }
1714	        }
1715	    }
1716	
1717	    int32_t const maxInputLength
1718	        = *std::max_element(context.effectivePrefillLengths.begin(), context.effectivePrefillLengths.end());
1719	    if (maxInputLength > mDeployment.base.maxSupportedInputLength)
1720	    {
1721	        LOG_ERROR("The max input length (%d) exceeds the max supported input length (%d) of the LLM Engine.",
1722	            maxInputLength, mDeployment.base.maxSupportedInputLength);
1723	        return false;
1724	    }
1725	
1726	    mSharedResources->cacheManagers[0]->resetForNewSequences(mHostReuseKVCacheLengths, context.stream);
1727	    if (needsStrategyKVCache)
1728	    {
1729	        strategy.resetForNewSequences(mHostReuseKVCacheLengths, context.stream);
1730	    }
1731	    return true;
1732	}
1733	
1734	bool LLMInferenceRuntime::genAndSaveSystemPromptKVCache(DecodingInferenceContext& context, int32_t genAndSaveBatchIdx)
1735	{
1736	    if (mDeployment.base.useVisionBidirectionalAttention)
1737	    {
1738	        LOG_ERROR("System-prompt KV-cache reuse is not supported with Gemma4 vision bidirectional attention.");
1739	        return false;
1740	    }
1741	
1742	    std::string const& loraWeightsName = context.loraWeightsName;
1743	    std::string const prompt = context.systemPrompts[genAndSaveBatchIdx];
1744	    auto const promptKey = keySystemPromptWithLoraWeights(prompt, loraWeightsName);
1745	
1746	    if (prompt.empty())
1747	    {
1748	        LOG_DEBUG("The systemPrompt is empty. Skip saving system prompt KVCache.");
1749	        return true;
1750	    }
1751	
1752	    DecodingStrategy& cacheStrategy = mDecoderRegistry->cachePrimingStrategy();
1753	    bool const hasDraft = cacheStrategy.isSpeculative();
1754	    auto baseCacheIt = mSystemPromptKVCacheBase.find(promptKey);
1755	    if (baseCacheIt != mSystemPromptKVCacheBase.end() && (!hasDraft || cacheStrategy.hasSystemPromptKVCache(promptKey)))
1756	    {
1757	        LOG_DEBUG("The system prompt KVCache already exists for the prompt: {%s}", prompt.c_str());
1758	        return true;
1759	    }
1760	    if (baseCacheIt != mSystemPromptKVCacheBase.end())
1761	    {
1762	        mSystemPromptKVCacheBase.erase(baseCacheIt);
1763	    }
1764	
1765	    auto tokenizedPrompt = mTokenizer->encode(prompt, true);
1766	    if (tokenizedPrompt.empty())
1767	    {
1768	        LOG_ERROR("Failed to encode system prompt for KVCache generation.");
1769	        return false;
1770	    }
1771	    int32_t const promptIdsLength = static_cast<int32_t>(tokenizedPrompt.size());
1772	
1773	    if (promptIdsLength > mDeployment.base.maxSupportedInputLength)
1774	    {
1775	        LOG_ERROR("System prompt length (%d) exceeds max supported input length (base=%d)", promptIdsLength,
1776	            mDeployment.base.maxSupportedInputLength);
1777	        return false;
1778	    }
1779	
1780	    if (hasDraft && promptIdsLength > mDeployment.draft->maxSupportedInputLength)
1781	    {
1782	        LOG_ERROR("System prompt length (%d) exceeds max supported input length (draft=%d)", promptIdsLength,
1783	            mDeployment.draft->maxSupportedInputLength);
1784	        return false;
1785	    }
1786	
1787	    // Temporary single-batch context to reuse the existing prefill functions.
1788	    DecodingInferenceContext tempContext;
1789	    tempContext.initialize(1, 1, context.visualEmbeddings, context.deepstackFeatures, loraWeightsName, context.stream);
1790	    tempContext.systemPrompts[0] = prompt;
1791	    tempContext.rawBatchedInputIds.push_back(tokenizedPrompt);
1792	    tempContext.tokenIds[0] = tokenizedPrompt;
1793	
1794	    if (!setUpForPrefillExecution(tempContext, cacheStrategy))
1795	    {
1796	        LOG_ERROR("Prefill execution setup failed for system prompt KVCache generation.");
1797	        return false;
1798	    }
1799	
1800	    bool prefillStatus = runBaseModelPrefill(tempContext);
1801	    if (!prefillStatus)
1802	    {
1803	        LOG_ERROR("Failed to execute base model prefill for system prompt KVCache generation.");
1804	        return false;
1805	    }
1806	
1807	    // Tokens produced during system KV-cache reuse prefill do not count as generated tokens.
1808	    tempContext.currentGenerateLengths[0] -= 1;
1809	
1810	    if (hasDraft)
1811	    {
1812	        bool draftPrefillStatus = cacheStrategy.runSystemPromptPrefill(tempContext);
1813	        if (!draftPrefillStatus)
1814	        {
1815	            LOG_ERROR("Failed to execute draft model prefill for system prompt KVCache generation.");
1816	            return false;
1817	        }
1818	    }
1819	    CUDA_CHECK(cudaStreamSynchronize(context.stream));
1820	
1821	    // Capture base KV cache content from the new-stack shared KV cache.
1822	    auto& cacheMgrBase = *mSharedResources->cacheManagers[0];
1823	    constexpr int32_t CACHE_BATCH_IDX{0};
1824	
1825	    SystemPromptKVCache savedKVCacheBase;
1826	    savedKVCacheBase.systemPrompt = prompt;
1827	    savedKVCacheBase.tokenizedPrompt = tokenizedPrompt;
1828	    savedKVCacheBase.kvCacheLayers = cacheMgrBase.captureKVCache(CACHE_BATCH_IDX, promptIdsLength, context.stream);
1829	
1830	    // Save recurrent / conv states for hybrid layers.
1831	    if (mDeployment.base.numLinearAttnLayers > 0)
1832	    {
1833	        savedKVCacheBase.recurrentStateContents = cacheMgrBase.captureRecurrentStates(CACHE_BATCH_IDX, context.stream);
1834	        savedKVCacheBase.convStateContents = cacheMgrBase.captureConvStates(CACHE_BATCH_IDX, context.stream);
1835	    }
1836	
1837	    mSystemPromptKVCacheBase.insert({promptKey, std::move(savedKVCacheBase)});
1838	
1839	    cacheStrategy.saveSystemPromptKVCache(promptKey, prompt, tokenizedPrompt, promptIdsLength, context.stream);
1840	
1841	    CUDA_CHECK(cudaStreamSynchronize(context.stream));
1842	    LOG_DEBUG("System prompt KVCache saved for batch %d: {%s}", genAndSaveBatchIdx, prompt.c_str());
1843	
1844	    return true;
1845	}
1846	
1847	bool LLMInferenceRuntime::genAndSaveSystemPromptKVCache(
1848	    std::string const& prompt, std::string const& loraWeightsName, cudaStream_t stream)
1849	{
1850	    if (mDeployment.base.useVisionBidirectionalAttention)
1851	    {
1852	        LOG_ERROR("System-prompt KV-cache reuse is not supported with Gemma4 vision bidirectional attention.");
1853	        return false;
1854	    }
1855	
1856	    if (prompt.empty())
1857	    {
1858	        LOG_DEBUG("The systemPrompt is empty. Skip saving system prompt KVCache.");
1859	        return true;
1860	    }
1861	    auto const promptKey = keySystemPromptWithLoraWeights(prompt, loraWeightsName);
1862	    DecodingStrategy& cacheStrategy = mDecoderRegistry->cachePrimingStrategy();
1863	    if (mSystemPromptKVCacheBase.find(promptKey) != mSystemPromptKVCacheBase.end()
1864	        && (!cacheStrategy.isSpeculative() || cacheStrategy.hasSystemPromptKVCache(promptKey)))
1865	    {
1866	        LOG_DEBUG("The system prompt KVCache already exists for the prompt: {%s}", prompt.c_str());
1867	        return true;
1868	    }
1869	    DecodingInferenceContext tempContext;
1870	    tempContext.initialize(1, 1, std::nullopt, rt::OptionalInputTensors{}, loraWeightsName, stream);
1871	    tempContext.systemPrompts[0] = prompt;
1872	    auto tokenizedPrompt = mTokenizer->encode(prompt, true);
1873	    if (tokenizedPrompt.empty())
1874	    {
1875	        LOG_ERROR("Failed to encode system prompt for KVCache generation.");
1876	        return false;
1877	    }
1878	    tempContext.rawBatchedInputIds.push_back(tokenizedPrompt);
1879	    tempContext.tokenIds[0] = tokenizedPrompt;
1880	    return genAndSaveSystemPromptKVCache(tempContext, 0);
1881	}
1882	
1883	bool LLMInferenceRuntime::performBatchEvict(DecodingInferenceContext& context, DecodingStrategy& strategy)
1884	{
1885	    // Check if any batch has finished
1886	    bool hasFinishedBatch = false;
1887	    for (int32_t i = 0; i < context.activeBatchSize; ++i)
1888	    {
1889	        if (context.finishedStates[i])
1890	        {
1891	            hasFinishedBatch = true;
1892	            break;
1893	        }
1894	    }
1895	
1896	    if (!hasFinishedBatch)
1897	    {
1898	        return true;
1899	    }
1900	
1901	    int32_t const oldActiveBatch = context.activeBatchSize;
1902	
1903	    // Build batch mapping
1904	    std::vector<int32_t> batchMapping = buildBatchMapping(context.finishedStates);
1905	
1906	    // Calculate new active batch size
1907	    int32_t newActiveBatch = 0;
1908	    for (auto newIdx : batchMapping)
1909	    {
1910	        if (newIdx >= 0)
1911	        {
1912	            newActiveBatch = std::max(newActiveBatch, newIdx + 1);
1913	        }
1914	    }
1915	
1916	    // Log eviction details
1917	    std::vector<int32_t> evictedIndices;
1918	    for (int32_t i = 0; i < oldActiveBatch; ++i)
1919	    {
1920	        if (batchMapping[i] < 0)
1921	        {
1922	            evictedIndices.push_back(i);
1923	        }
1924	    }
1925	    LOG_DEBUG("Batch eviction: %d active batches to %d remaining (evicted %d batch(es): indices [%s])", oldActiveBatch,
1926	        newActiveBatch, static_cast<int32_t>(evictedIndices.size()),
1927	        [&evictedIndices]() {
1928	            std::string result;
1929	            for (size_t i = 0; i < evictedIndices.size(); ++i)
1930	            {
1931	                if (i > 0)
1932	                {
1933	                    result += ", ";
1934	                }
1935	                result += std::to_string(evictedIndices[i]);
1936	            }
1937	            return result;
1938	        }()
1939	            .c_str());
1940	
1941	    // Upload batch mapping to GPU
1942	    check::check(mDeviceBatchMapping.reshape({oldActiveBatch}), "Tensor reshape failed");
1943	    CUDA_CHECK(cudaMemcpyAsync(mDeviceBatchMapping.rawPointer(), batchMapping.data(), oldActiveBatch * sizeof(int32_t),
1944	        cudaMemcpyHostToDevice, context.stream));
1945	
1946	    // Compact base model caches (KV + Mamba) via the HybridCacheManager single-call API.
1947	    mSharedResources->cacheManagers[0]->compactBatch(
1948	        mDeviceBatchMapping, oldActiveBatch, newActiveBatch, context.stream);
1949	    mSharedResources->cacheManagers[0]->setActiveBatchSize(newActiveBatch);
1950	
1951	    // Compact base model's RoPE cache (stored per-batch for MRope on mPipelineIO->mropeCosSin).
1952	    if (mDeployment.base.ropeConfig.type == RopeType::kMRope && newActiveBatch > 0)
1953	    {
1954	        rt::Tensor& baseRopeCache = mPipelineIO->mropeCosSin;
1955	        if (baseRopeCache.getShape().getNumDims() == 3 && baseRopeCache.getShape()[0] == oldActiveBatch)
1956	        {
1957	            kernel::compactTensorBatch(
1958	                baseRopeCache, mDeviceBatchMapping, baseRopeCache, oldActiveBatch, newActiveBatch, context.stream);
1959	            auto const seqLen = static_cast<int32_t>(baseRopeCache.getShape()[1]);
1960	            auto const rotaryDim = static_cast<int32_t>(baseRopeCache.getShape()[2]);
1961	            check::check(baseRopeCache.reshape({newActiveBatch, seqLen, rotaryDim}), "Tensor reshape failed");
1962	        }
1963	    }
1964	
1965	    strategy.onBatchEvict(batchMapping, oldActiveBatch, newActiveBatch, mDeviceBatchMapping, context.stream);
1966	
1967	    // Compact CPU context
1968	    CUDA_CHECK(cudaStreamSynchronize(context.stream));
1969	
1970	    // Save evicted batches' results before compacting (using original batch index)
1971	    for (size_t i = 0; i < batchMapping.size(); ++i)
1972	    {
1973	        if (batchMapping[i] < 0 && context.finishedStates[i])
1974	        {
1975	            // This batch is evicted and finished, save its results with original index
1976	            int32_t originalIdx = context.batchIndexMapping[i];
1977	
1978	            // Create and populate BatchResult with all related data
1979	            BatchResult result;
1980	            result.tokenIds = std::move(context.tokenIds[i]);
1981	            result.generateLength = context.currentGenerateLengths[i];
1982	            result.actualIterations = context.generationRound;
1983	            result.rawBatchedInputIds = std::move(context.rawBatchedInputIds[i]);
1984	            result.effectivePrefillLength = context.effectivePrefillLengths[i];
1985	            result.terminalReason = context.slotStreams[i].terminalReason;
1986	            // Convert flat LogprobsSlot → nested vector for BatchResult (once per completed request).
1987	            // Enrich each (token_id, logprob) with the raw token piece so consumers can render the
1988	            // token string / bytes without needing a tokenizer (see LogprobEntry).
1989	            rt::LogprobsSlot const& slot = context.stepLogprobs[i];
1990	            result.logprobs.resize(slot.numSteps);
1991	            for (int32_t step = 0; step < slot.numSteps; ++step)
1992	            {
1993	                auto const* begin = slot.data.data() + step * context.numLogprobs;
1994	                auto& stepEntries = result.logprobs[step];
1995	                stepEntries.reserve(context.numLogprobs);
1996	                for (int32_t k = 0; k < context.numLogprobs; ++k)
1997	                {
1998	                    stepEntries.push_back({begin[k].first, begin[k].second, mTokenizer->idToPiece(begin[k].first)});
1999	                }
2000	            }
2001	
2002	            context.completedBatches[originalIdx] = std::move(result);
2003	        }
2004	    }
2005	
2006	    rt::compactVector(batchMapping, context.finishedStates);
2007	    rt::compactVector(batchMapping, context.currentGenerateLengths);
2008	    rt::compactVector(batchMapping, context.tokenIds);
2009	    rt::compactVector(batchMapping, context.systemPrompts);
2010	    rt::compactVector(batchMapping, context.rawBatchedInputIds);
2011	    rt::compactVector(batchMapping, context.effectivePrefillLengths);
2012	    rt::compactVector(batchMapping, context.batchIndexMapping);
2013	    rt::compactVector(batchMapping, context.slotStreams);
2014	    rt::compactVector(batchMapping, context.stopStringsPerSlot);
2015	    rt::compactVector(batchMapping, context.logitBiasPerSlot);
2016	    context.hasLogitBias = std::any_of(context.logitBiasPerSlot.begin(), context.logitBiasPerSlot.end(),
2017	        [](auto const& slotLogitBias) { return !slotLogitBias.empty(); });
2018	    context.logitBiasGpuDirty = context.hasLogitBias;
2019	    rt::compactVector(batchMapping, context.stepLogprobs);
2020	
2021	    // Update active batch size
2022	    context.activeBatchSize = newActiveBatch;
2023	
2024	    return true;
2025	}
2026	
2027	} // namespace rt
2028	} // namespace trt_edgellm
