575	        }
576	        catch (std::exception const& e)
577	        {
578	            LOG_ERROR("Failed to initialize runtime with speculative decoding: %s", e.what());
579	            return EXIT_FAILURE;
580	        }
581	    }
582	    else
583	    {
584	        // Standard vanilla-only mode (no draft model)
585	        try
586	        {
587	            runtime = std::make_unique<rt::LLMInferenceRuntime>(
588	                args.engineDir, args.multimodalEngineDir, loraWeightsMap, stream);
589	        }
590	        catch (std::exception const& e)
591	        {
592	            LOG_ERROR("Failed to initialize runtime: %s", e.what());
593	            return EXIT_FAILURE;
594	        }
595	    }
596	
597	    if (!runtime->captureDecodingCUDAGraph(stream))
598	    {
599	        LOG_WARNING("Failed to capture CUDA graph for decoding, proceeding with normal engine execution.");
600	    }
601	
602	    // Initialize Qwen3-Omni audio output pipeline (TTS runtime + Code2Wav)
603	    std::unique_ptr<rt::Qwen3OmniTTSRuntime> ttsRuntime;
604	    std::unique_ptr<rt::Code2WavRunner> code2wavRunner;
605	    if (args.enableAudioOutput)
606	    {
607	        try
608	        {
609	            std::filesystem::path const codePredictorDir
610	                = std::filesystem::path(args.talkerEngineDir).parent_path() / "code_predictor";
611	            ttsRuntime = std::make_unique<rt::Qwen3OmniTTSRuntime>(
612	                args.talkerEngineDir, codePredictorDir.string(), args.engineDir, stream);
613	            LOG_INFO("TTS runtime initialized for audio output");
614	        }
615	        catch (std::exception const& e)
616	        {
617	            LOG_ERROR("Failed to initialize TTS Runtime: %s", e.what());
618	            return EXIT_FAILURE;
619	        }
620	
621	        // Code2Wav runner (optional — falls back to RVQ code output)
622	        std::filesystem::path const code2wavDir = args.code2wavEngineDir.empty()
623	            ? std::filesystem::path(args.talkerEngineDir).parent_path() / "code2wav"
624	            : std::filesystem::path(args.code2wavEngineDir);
625	        if (std::filesystem::exists(code2wavDir))
626	        {
627	            try
628	            {
629	                code2wavRunner = std::make_unique<rt::Code2WavRunner>(code2wavDir.string(), stream);
630	                LOG_INFO("Code2Wav runner initialized");
631	            }
632	            catch (std::exception const& e)
633	            {
634	                LOG_WARNING("Failed to initialize Code2Wav: %s. Will output RVQ codes only.", e.what());
635	            }
636	        }
637	
638	        if (!ttsRuntime->captureDecodingCUDAGraph(stream))
639	        {
640	            LOG_WARNING("CUDA graph capture failed for TTS decoding, proceeding without.");
641	        }
642	
643	        if (!args.outputAudioDir.empty())
644	        {
645	            std::filesystem::create_directories(args.outputAudioDir);
646	        }
647	    }
648	
649	    // Perform warmup runs if requested
650	    if (args.warmup > 0)
651	    {
652	        // Disable profiling for warmup runs
653	        setProfilingEnabled(false);
654	        LOG_INFO("Starting warmup with %d runs using the first request...", args.warmup);
655	        auto& firstRequest = batchedRequests[0];
656	
657	        for (int32_t warmupRun = 0; warmupRun < args.warmup; ++warmupRun)
658	        {
659	            rt::LLMGenerationResponse warmupResponse;
660	            bool requestStatus = runtime->handleRequest(firstRequest, warmupResponse, stream);
661	
662	            if (!requestStatus)
663	            {
664	                LOG_ERROR("Warmup run %d/%d failed", warmupRun + 1, args.warmup);
665	                return EXIT_FAILURE;
666	            }
667	        }
668	        LOG_INFO("Warmup of %d runs completed. Starting actual benchmark runs...", args.warmup);
669	    }
670	
671	    if (profilerEnabled)
672	    {
673	        setProfilingEnabled(true);
674	    }
675	
676	    // Structure to collect all responses for JSON export
677	    nlohmann::json outputData;
678	    outputData["input_file"] = args.inputFile;
679	    outputData["responses"] = nlohmann::json::array();
680	
681	    bool hasFailedRequest = false;
682	    std::string errorMessage = "TensorRT Edge LLM cannot handle this request. Fails.";
683	    size_t failedCount = 0;
684	    // Index of the request in the input file's flat "requests" array. Batching packs
685	    // batchSize consecutive requests into one batched request, so downstream consumers
686	    // (e.g. calculate_wer_score.py) must receive the flat index, not the batch index.
687	    size_t flatRequestIdx = 0;
688	
689	    // Process each request with progress indication
690	    LOG_INFO("Processing %zu batched requests...", batchedRequests.size());
691	    for (size_t requestIdx = 0; requestIdx < batchedRequests.size(); ++requestIdx)
692	    {
693	        auto& request = batchedRequests[requestIdx];
694	        rt::LLMGenerationResponse response;
695	
696	        // Show progress every 10% or every 100 requests, whichever is smaller
697	        size_t progressInterval = std::max(size_t(1), std::min(batchedRequests.size() / 10, size_t(100)));
698	        if ((requestIdx + 1) % progressInterval == 0 || requestIdx == 0 || requestIdx == batchedRequests.size() - 1)
699	        {
700	            LOG_INFO("Progress: %zu/%zu (%f%%)", requestIdx + 1, batchedRequests.size(),
701	                100.0 * (requestIdx + 1) / batchedRequests.size());
702	        }
703	
704	        bool requestStatus = false;
705	        StreamingAudioWriter streamingWriter;
706	
707	        cudaEvent_t e2eStart{nullptr}, e2eEnd{nullptr}, ttfpaEvent{nullptr};
708	        bool ttfpaRecorded = false;
709	        if (getProfilingEnabled() && ttsRuntime)
710	        {
711	            CUDA_CHECK(cudaEventCreateWithFlags(&e2eStart, cudaEventDefault));
712	            CUDA_CHECK(cudaEventCreateWithFlags(&e2eEnd, cudaEventDefault));
713	            CUDA_CHECK(cudaEventCreateWithFlags(&ttfpaEvent, cudaEventDefault));
714	            CUDA_CHECK(cudaEventRecord(e2eStart, stream));
715	        }
716	
717	        // Streaming path: Thinker + Talker interleaved on the same CUDA stream
718	        rt::Qwen3OmniTTSRuntime::TalkerGenerationResponse streamingTalkerResp;
719	        if (args.enableThinkerTalkerStreaming && ttsRuntime)
720	        {
721	            rt::Qwen3OmniTTSRuntime::OmniGenerationRequest omniBaseReq;
722	            omniBaseReq.talkerTemperature = args.talkerTemperature;
723	            omniBaseReq.talkerTopK = args.talkerTopK;
724	            omniBaseReq.talkerTopP = args.talkerTopP;
725	            omniBaseReq.repetitionPenalty = args.talkerRepetitionPenalty;
726	
727	            rt::Qwen3OmniTTSRuntime::ThinkerTalkerStreamingConfig streamCfg;
728	            streamCfg.talkerPrefillThreshold = args.talkerPrefillThreshold;
729	
730	            if (!args.outputAudioDir.empty() && code2wavRunner)
731	            {
732	                std::string filename = format::fmtstr("audio_req%zu_batch0.wav", requestIdx);
733	                std::filesystem::path audioPath = std::filesystem::path(args.outputAudioDir) / filename;
734	                streamingWriter.open(audioPath.string(), 24000);
735	
736	                streamCfg.codecChunkFrames = args.codecChunkFrames;
737	                streamCfg.onAudioChunkReady
738	                    = [&](std::vector<std::vector<int32_t>> const& chunkCodes, bool /*isFinal*/) {
739	                          if (chunkCodes.empty() || !code2wavRunner)
740	                              return;
741	                          size_t const numFrames = chunkCodes.size();
742	                          size_t const numLayers = chunkCodes[0].size();
743	                          std::vector<std::vector<int32_t>> transposed(numLayers, std::vector<int32_t>(numFrames));
744	                          for (size_t f = 0; f < numFrames; ++f)
745	                              for (size_t l = 0; l < numLayers; ++l)
746	                                  transposed[l][f] = chunkCodes[f][l];
747	
748	                          rt::audioUtils::AudioData chunkAudio;
749	                          code2wavRunner->generateWaveform(transposed, chunkAudio, stream);
750	                          if (chunkAudio.hasWaveform)
751	                          {
752	                              streamingWriter.appendChunk(chunkAudio);
753	                              if (!ttfpaRecorded && ttfpaEvent)
754	                              {
755	                                  CUDA_CHECK(cudaEventRecord(ttfpaEvent, stream));
756	                                  ttfpaRecorded = true;
757	                              }
758	                          }
759	                      };
760	            }
761	
762	            request.generateAudio = true;
763	
764	            requestStatus = ttsRuntime->handleStreamingGeneration(
765	                *runtime, request, response, streamCfg, omniBaseReq, streamingTalkerResp, stream);
766	
767	            if (requestStatus)
768	            {
769	                LOG_INFO("Request %zu: Thinker-Talker streaming generated %d audio frames", requestIdx,
770	                    streamingTalkerResp.numFramesPerSample.empty() ? 0 : streamingTalkerResp.numFramesPerSample[0]);
771	            }
772	        }
773	        else
774	        {
775	            // Sequential Omni: tell the runtime which hidden layer the Talker needs so it
776	            // registers mOutputHiddenStates under that layer in the portal (not layer 0).
777	            if (args.enableAudioOutput && ttsRuntime)
778	            {
779	                std::vector<int32_t> const requiredLayers = ttsRuntime->getThinkerHiddenLayerIndices();
780	                request.acceptHiddenLayer = (requiredLayers.size() >= 2) ? requiredLayers[1] : 14;
781	            }
782	            requestStatus = runtime->handleRequest(request, response, stream, args.enableAudioOutput);
783	        }
784	
785	        // Qwen3-Omni audio generation: Code2Wav vocoding
786	        std::vector<rt::audioUtils::AudioData> audioOutputs;
787	
788	        // Helper: transpose RVQ codes [frames][layers] → [layers][frames] and vocode
789	        auto vocodeAndSave = [&](std::vector<std::vector<int32_t>> const& framesCodes, size_t batchIdx) {
790	            if (framesCodes.empty() || framesCodes[0].empty() || !code2wavRunner)
791	                return;
792	            size_t const numFrames = framesCodes.size();
793	            size_t const numLayers = framesCodes[0].size();
794	            std::vector<std::vector<int32_t>> transposed(numLayers, std::vector<int32_t>(numFrames));
795	            for (size_t f = 0; f < numFrames; ++f)
796	                for (size_t l = 0; l < numLayers; ++l)
797	                    transposed[l][f] = framesCodes[f][l];
798	
799	            if (args.dumpOutput)
800	            {
801	                int32_t codeMin = transposed[0][0], codeMax = transposed[0][0];
802	                for (auto const& row : transposed)
803	                    for (int32_t c : row)
804	                    {
805	                        codeMin = std::min(codeMin, c);
806	                        codeMax = std::max(codeMax, c);
807	                    }
808	                LOG_INFO("Batch %zu: RVQ codes %zu frames x %zu layers, range [%d, %d]", batchIdx, numFrames, numLayers,
809	                    codeMin, codeMax);
810	            }
811	
812	            rt::audioUtils::AudioData audioData;
813	            if (code2wavRunner->generateWaveform(transposed, audioData, stream) && audioData.hasWaveform)
814	            {
815	                if (!args.outputAudioDir.empty())
816	                {
817	                    std::string filename = format::fmtstr("audio_req%zu_batch%zu.wav", requestIdx, batchIdx);
818	                    std::filesystem::path audioPath = std::filesystem::path(args.outputAudioDir) / filename;
819	                    saveAudioToWav(audioPath.string(), audioData);
820	                    LOG_INFO("Audio saved: %s", audioPath.string().c_str());
821	                }
822	                audioOutputs.push_back(std::move(audioData));
823	            }
824	        };
825	
826	        // Streaming path: vocode the streaming RVQ codes
827	        if (requestStatus && args.enableThinkerTalkerStreaming && !streamingTalkerResp.batchRvqCodes.empty())
828	        {
829	            if (streamingWriter.totalSamplesWritten() > 0)
830	            {
831	                streamingWriter.finalize();
832	                LOG_INFO("Streaming audio written: %ld samples (%.2fs)", streamingWriter.totalSamplesWritten(),
833	                    static_cast<float>(streamingWriter.totalSamplesWritten()) / 24000.0f);
834	            }
835	            else
836	            {
837	                for (size_t batchIdx = 0; batchIdx < streamingTalkerResp.batchRvqCodes.size(); ++batchIdx)
838	                {
839	                    vocodeAndSave(streamingTalkerResp.batchRvqCodes[batchIdx], batchIdx);
840	                }
841	            }
842	        }
843	
844	        // Non-streaming path: build batched Omni requests and call Talker once.
845	        // Fetch Thinker prefill embeddings / hidden states from the runtime portal
846	        // (see LLMInferenceRuntime::getBaseModelHiddenStates contract).
847	        rt::Tensor const* prefillEmbedsAll = runtime->getBaseModelHiddenStates(0);
848	        std::vector<int32_t> const requiredLayers
849	            = ttsRuntime ? ttsRuntime->getThinkerHiddenLayerIndices() : std::vector<int32_t>{};
850	        int32_t const acceptHiddenLayer = (requiredLayers.size() >= 2) ? requiredLayers[1] : 14;
851	        rt::Tensor const* hiddenStatesAll = runtime->getBaseModelHiddenStates(acceptHiddenLayer);
852	        auto const& thinkerInputTokenIds = runtime->getBaseModelInputTokenIds();
853	
854	        if (requestStatus && !args.enableThinkerTalkerStreaming && args.enableAudioOutput && ttsRuntime
855	            && prefillEmbedsAll != nullptr && !prefillEmbedsAll->isEmpty())
856	        {
857	            int32_t const prefillLen = runtime->getBaseModelPrefillLength();
858	            int64_t const H = prefillEmbedsAll->getShape()[2];
859	            int64_t const batchStride = static_cast<int64_t>(prefillLen) * H;
860	
861	            // Per-batch views into the [BS, prefillLen, H] tensors (must outlive omniRequests)
862	            size_t const batchSize = response.outputIds.size();
863	            std::vector<rt::Tensor> perBatchEmbedViews(batchSize);
864	            std::vector<rt::Tensor> perBatchHiddenViews(batchSize);
865	
866	            std::vector<rt::Qwen3OmniTTSRuntime::OmniGenerationRequest> omniRequests;
867	            for (size_t batchIdx = 0; batchIdx < batchSize; ++batchIdx)
868	            {
869	                rt::Qwen3OmniTTSRuntime::OmniGenerationRequest omniReq;
870	                if (batchIdx < thinkerInputTokenIds.size())
871	                {
872	                    omniReq.textTokenIds = thinkerInputTokenIds[batchIdx];
873	                    omniReq.textTokenIds.insert(omniReq.textTokenIds.end(), response.outputIds[batchIdx].begin(),
874	                        response.outputIds[batchIdx].end());
875	                }
876	                omniReq.talkerTemperature = args.talkerTemperature;
877	                omniReq.talkerTopK = args.talkerTopK;
878	                omniReq.talkerTopP = args.talkerTopP;
879	                omniReq.repetitionPenalty = args.talkerRepetitionPenalty;
880	
881	                __half* embedBase = static_cast<__half*>(const_cast<void*>(prefillEmbedsAll->rawPointer()))
882	                    + static_cast<int64_t>(batchIdx) * batchStride;
883	                perBatchEmbedViews[batchIdx] = rt::Tensor(embedBase, rt::Coords{1, static_cast<int64_t>(prefillLen), H},
884	                    rt::DeviceType::kGPU, nvinfer1::DataType::kHALF);
885	                omniReq.thinkerPrefillEmbeds = &perBatchEmbedViews[batchIdx];
886	
887	                if (hiddenStatesAll != nullptr)
888	                {
889	                    __half* hiddenBase = static_cast<__half*>(const_cast<void*>(hiddenStatesAll->rawPointer()))
890	                        + static_cast<int64_t>(batchIdx) * batchStride;
891	                    perBatchHiddenViews[batchIdx]
892	                        = rt::Tensor(hiddenBase, rt::Coords{1, static_cast<int64_t>(prefillLen), H},
893	                            rt::DeviceType::kGPU, nvinfer1::DataType::kHALF);
894	                    omniReq.thinkerHiddenStates = &perBatchHiddenViews[batchIdx];
895	                }
896	
897	                omniReq.prefillLength = batchIdx < thinkerInputTokenIds.size()
898	                    ? static_cast<int32_t>(thinkerInputTokenIds[batchIdx].size())
899	                    : 0;
900	                omniRequests.push_back(std::move(omniReq));
901	            }
902	
903	            rt::Qwen3OmniTTSRuntime::TalkerGenerationResponse talkerResp;
904	            if (ttsRuntime->handleAudioGenerationFromThinker(omniRequests, talkerResp, stream))
905	            {
906	                for (size_t batchIdx = 0; batchIdx < talkerResp.batchRvqCodes.size(); ++batchIdx)
907	                {
908	                    vocodeAndSave(talkerResp.batchRvqCodes[batchIdx], batchIdx);
909	                }
910	            }
911	            else
912	            {
913	                LOG_WARNING("Batched audio generation failed for request %zu", requestIdx);
914	            }
915	        }
916	
917	        if (e2eStart && e2eEnd && ttsRuntime)
918	        {
919	            CUDA_CHECK(cudaEventRecord(e2eEnd, stream));
920	            CUDA_CHECK(cudaEventSynchronize(e2eEnd));
921	
922	            auto& latency = ttsRuntime->getMutableOmniLatencyMetrics();
923	
924	            float e2eMs = 0.0f;
925	            CUDA_CHECK(cudaEventElapsedTime(&e2eMs, e2eStart, e2eEnd));
926	            latency.endToEndMs = e2eMs;
927	
928	            auto const& ttfaEnd = ttsRuntime->getTtfaEndEvent();
929	            if (ttfaEnd)
930	            {
931	                CUDA_CHECK(cudaEventSynchronize(ttfaEnd));
932	                float ttfaMs = 0.0f;
933	                CUDA_CHECK(cudaEventElapsedTime(&ttfaMs, e2eStart, ttfaEnd));
934	                latency.timeToFirstAudioCodeMs = ttfaMs;
935	            }
936	
937	            if (ttfpaRecorded && ttfpaEvent)
938	            {
939	                CUDA_CHECK(cudaEventSynchronize(ttfpaEvent));
940	                float ttfpaMs = 0.0f;
941	                CUDA_CHECK(cudaEventElapsedTime(&ttfpaMs, e2eStart, ttfpaEvent));
942	                latency.timeToFirstPlayableAudioMs = ttfpaMs;
943	            }
944	            else
945	            {
946	                latency.timeToFirstPlayableAudioMs = e2eMs;
947	            }
948	
949	            cudaEventDestroy(e2eStart);
950	            cudaEventDestroy(e2eEnd);
951	            if (ttfpaEvent)
952	            {
953	                cudaEventDestroy(ttfpaEvent);
954	            }
955	        }
956	
957	        if (requestStatus)
958	        {
959	            if (args.dumpOutput)
960	            {
961	                for (size_t batchIdx = 0; batchIdx < response.outputTexts.size(); ++batchIdx)
962	                {
963	                    char const* reasonName = batchIdx < response.finishReasons.size()
964	                        ? rt::finishReasonName(response.finishReasons[batchIdx])
965	                        : "?";
966	                    LOG_INFO("Response for request %zu batch %zu [finish=%s]: %s", requestIdx, batchIdx, reasonName,
967	                        response.outputTexts[batchIdx].c_str());
968	                    if (batchIdx < audioOutputs.size() && audioOutputs[batchIdx].waveform
969	                        && !audioOutputs[batchIdx].waveform->isEmpty())
970	                    {
971	                        auto const& shape = audioOutputs[batchIdx].waveform->getShape();
972	                        int64_t samples = shape[shape.getNumDims() - 1];
973	                        LOG_INFO("  Audio: %ld samples (%.2fs)", samples,
974	                            static_cast<float>(samples) / audioOutputs[batchIdx].sampleRate);
975	                    }
976	                }
977	            }
978	        }
979	        else
980	        {
981	            hasFailedRequest = true;
982	            failedCount++;
983	            LOG_ERROR("*** FAILED *** Request %zu failed to process!", requestIdx);
984	        }
985	
986	        // Add to JSON output with UTF-8 validation on output text
987	        for (size_t batchIdx = 0; batchIdx < request.requests.size(); ++batchIdx)
988	        {
989	            nlohmann::json responseJson;
990	            bool const hasOutputText = requestStatus && batchIdx < response.outputTexts.size();
991	            std::string outputText = hasOutputText ? response.outputTexts[batchIdx] : errorMessage;
992	            auto const* formattedRequest
993	                = batchIdx < request.formattedRequests.size() ? &request.formattedRequests[batchIdx] : nullptr;
994	            // Validate UTF-8 for output text (inputs are always valid)
995	            // If invalid UTF-8 detected, error message is returned and original text is logged
996	            responseJson["output_text"] = sanitizeUtf8ForJson(outputText);
997	            responseJson["request_idx"] = flatRequestIdx++;
998	            responseJson["batch_idx"] = batchIdx;
999	            responseJson["finish_reason"] = (requestStatus && batchIdx < response.finishReasons.size())
1000	                ? rt::finishReasonName(response.finishReasons[batchIdx])
1001	                : "error";
1002	            // Store messages for reference
1003	            nlohmann::json messagesJson = nlohmann::json::array();
1004	            for (auto const& msg : request.requests[batchIdx].messages)
1005	            {
1006	                nlohmann::json msgJson;
1007	                msgJson["role"] = msg.role;
1008	                msgJson["content"] = nlohmann::json::array();
1009	                for (auto const& content : msg.contents)
1010	                {
1011	                    nlohmann::json contentJson;
1012	                    contentJson["type"] = content.type;
1013	                    if (content.type == "text")
1014	                    {
1015	                        contentJson["text"] = content.content;
1016	                    }
1017	                    else if (content.type == "image")
1018	                    {
1019	                        contentJson["image"] = content.content;
1020	                    }
1021	                    else if (content.type == "video")
1022	                    {
1023	                        contentJson["video"] = content.content;
1024	                    }
1025	                    msgJson["content"].push_back(contentJson);
1026	                }
1027	                messagesJson.push_back(msgJson);
1028	            }
1029	            responseJson["messages"] = messagesJson;
1030	            // Store formatted prompts for reference
1031	            responseJson["formatted_system_prompt"] = formattedRequest ? formattedRequest->formattedSystemPrompt : "";
1032	            responseJson["formatted_complete_request"]
1033	                = formattedRequest ? formattedRequest->formattedCompleteRequest : "";
1034	            // Serialize logprobs if present: logprobs[step] = [{token_id, token, bytes, logprob}, ...]
1035	            // `token` is the UTF-8-sanitized piece string (invalid bytes -> U+FFFD, required so
1036	            // nlohmann::json::dump does not throw); `bytes` carries the raw token bytes losslessly.
1037	            if (requestStatus && batchIdx < response.logprobs.size() && !response.logprobs[batchIdx].empty())
1038	            {
1039	                nlohmann::json logprobsJson = nlohmann::json::array();
1040	                for (auto const& stepEntries : response.logprobs[batchIdx])
1041	                {
1042	                    nlohmann::json stepJson = nlohmann::json::array();
1043	                    for (auto const& entry : stepEntries)
1044	                    {
1045	                        std::string pending;
1046	                        std::string token = utf8::sanitizeUtf8Streaming(entry.piece, pending);
1047	                        token += utf8::sanitizeUtf8Flush(pending);
1048	                        nlohmann::json bytesJson = nlohmann::json::array();
1049	                        for (unsigned char b : entry.piece)
1050	                        {
1051	                            bytesJson.push_back(static_cast<int>(b));
1052	                        }
1053	                        stepJson.push_back({{"token_id", entry.tokenId}, {"token", std::move(token)},
1054	                            {"bytes", std::move(bytesJson)}, {"logprob", entry.logprob}});
1055	                    }
1056	                    logprobsJson.push_back(std::move(stepJson));
1057	                }
1058	                responseJson["logprobs"] = std::move(logprobsJson);
1059	            }
1060	            outputData["responses"].push_back(responseJson);
1061	        }
1062	    }
1063	
1064	    // Final processing summary
1065	    LOG_INFO("Processing complete: %zu/%zu batched requests successful", batchedRequests.size() - failedCount,
1066	        batchedRequests.size());
1067	    if (failedCount > 0)
1068	    {
1069	        LOG_ERROR("*** %zu BATCHED REQUESTS FAILED ***", failedCount);
1070	    }
1071	
1072	    if (profilerEnabled)
1073	    {
1074	        // Stop memory monitoring for examples
1075	        setProfilingEnabled(false);
1076	        memoryMonitor.stop();
1077	    }
1078	
1079	    if (args.dumpProfile)
1080	    {
1081	        std::ostringstream profileOutput;
1082	        profileOutput << std::endl;
1083	        profileOutput << "=== Performance Summary ===" << std::endl;
1084	        auto prefillMetrics = runtime->getPrefillMetrics();
1085	        auto multimodalMetrics = runtime->getMultimodalMetrics();
1086	        outputPrefillProfile(profileOutput, prefillMetrics);
1087	        if (args.specDecodeArgs.enabled)
1088	        {
1089	            auto specDecodeGenerationMetrics = runtime->getSpecDecodeGenerationMetrics();
1090	            outputSpecDecodeGenerationProfile(
1091	                profileOutput, specDecodeGenerationMetrics, runtime->getSpeculativeDecodingStrategyName());
1092	        }
1093	        else
1094	        {
1095	            outputGenerationProfile(profileOutput, runtime->getGenerationMetrics());
1096	        }
1097	        outputMultimodalProfile(profileOutput, multimodalMetrics);
1098	        if (ttsRuntime)
1099	        {
1100	            outputTalkerProfile(profileOutput, ttsRuntime->getMetrics());
1101	            outputOmniProfile(profileOutput, ttsRuntime->getOmniTalkerMetrics(), ttsRuntime->getOmniLatencyMetrics());
1102	        }
1103	        outputMemoryProfile(profileOutput, memoryMonitor);
1104	        profileOutput << "=====================================" << std::endl;
1105	        LOG_INFO("%s", profileOutput.str().c_str());
1106	    }
1107	
1108	    // Export profile to JSON file
1109	    if (!args.profileOutputFile.empty())
1110	    {
1111	        try
1112	        {
1113	            nlohmann::json profileJson;
1114	
1115	            // Add high-level metrics from unified runtime
1116	            addJsonPrefillSummary(profileJson, runtime->getPrefillMetrics());
1117	            if (args.specDecodeArgs.enabled)
1118	            {
1119	                addJsonSpecDecodeGenerationSummary(profileJson, runtime->getSpecDecodeGenerationMetrics(),
1120	                    runtime->getSpeculativeDecodingStrategyName());
1121	            }
1122	            else
1123	            {
1124	                addJsonGenerationSummary(profileJson, runtime->getGenerationMetrics());
1125	            }
1126	            addJsonMultimodalSummary(profileJson, runtime->getMultimodalMetrics());
1127	            if (ttsRuntime)
1128	            {
1129	                addJsonTalkerSummary(profileJson, ttsRuntime->getMetrics());
1130	            }
1131	
1132	            // Add detailed timing stages
1133	            addJsonTimingStages(profileJson);
1134	
1135	            if (ttsRuntime)
1136	            {
1137	                addJsonOmniStageExtensions(
1138	                    profileJson, ttsRuntime->getOmniTalkerMetrics(), ttsRuntime->getOmniLatencyMetrics());
1139	            }
1140	
1141	            // Add memory usage
1142	            addJsonMemorySummary(profileJson, memoryMonitor);
1143	
1144	            std::ofstream profileFile(args.profileOutputFile);
1145	            if (profileFile.is_open())
1146	            {
1147	                profileFile << profileJson.dump(2); // Pretty print with 2 space indentation
1148	                profileFile.close();
1149	                LOG_INFO("Profile data exported to: %s", args.profileOutputFile.c_str());
1150	            }
1151	            else
1152	            {
1153	                LOG_ERROR("Failed to open profile output file: %s", args.profileOutputFile.c_str());
1154	                return EXIT_FAILURE;
1155	            }
1156	        }
1157	        catch (std::exception const& e)
1158	        {
1159	            LOG_ERROR("Failed to write profile output file: %s", e.what());
1160	            return EXIT_FAILURE;
1161	        }
1162	    }
1163	
1164	    // Export to JSON file
1165	    try
1166	    {
1167	        std::ofstream outputFile(args.outputFile);
1168	        if (outputFile.is_open())
1169	        {
1170	            outputFile << outputData.dump(4); // Pretty print with 4 spaces indentation
1171	            outputFile.close();
1172	            LOG_INFO("All responses exported to: %s", args.outputFile.c_str());
1173	        }
1174	        else
1175	        {
1176	            LOG_ERROR("Failed to open output file: %s", args.outputFile.c_str());
1177	            return EXIT_FAILURE;
1178	        }
1179	    }
1180	    catch (std::exception const& e)
1181	    {
1182	        LOG_ERROR("Failed to write output file: %s", e.what());
1183	        return EXIT_FAILURE;
1184	    }
1185	
1186	    // Return false if any request failed
1187	    return hasFailedRequest ? EXIT_FAILURE : EXIT_SUCCESS;
1188	}
1189

